const PLACES=[{"id": "g-abusimbel", "image": "places/g-abusimbel.jpg", "level": 0, "country": "Egypt", "title": "Giants in the cliff", "alt": "A temple front carved straight into a sandstone cliff, with tall standing statues of a king and queen either side of the door.", "clue": "Temples carved into a cliff by a great pharaoh, moved piece by piece to higher ground when a huge dam was built.", "story": "The temples of Abu Simbel in Egypt were cut into the rock over 3,200 years ago. In the 1960s they were sawn into blocks and moved to save them from the rising Lake Nasser.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Templo_de_Nefertari,_Abu_Simbel,_Egipto,_2022-04-02,_DD_153.jpg"}, {"id": "g-acropolis", "image": "places/g-acropolis.jpg", "level": 0, "country": "Greece", "title": "A temple on the hill", "alt": "Ancient marble temple ruins on a rocky hilltop above green trees.", "clue": "A temple to the city's patron goddess, on a rock above the birthplace of democracy.", "story": "The Parthenon on the Acropolis of Athens was built in the 400s BC for the goddess Athena.", "credit": "A.Savin / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Attica_06-13_Athens_50_View_from_Philopappos_-_Acropolis_Hill.jpg"}, {"id": "g-alhambra", "image": "places/g-alhambra.jpg", "level": 0, "country": "Spain", "title": "A red fortress at sunset", "alt": "Reddish fortress walls and towers on a wooded hill, glowing in evening light with mountains behind.", "clue": "A red fortress-palace of Moorish sultans, glowing at sunset above a city near snowy mountains.", "story": "The Alhambra in Granada, Spain, was built mainly by the Nasrid sultans in the 1200s and 1300s. Its name comes from the Arabic for \"the red one\", after the colour of its walls.", "credit": "Jebulon / Wikimedia Commons", "licence": "Public domain", "licenseUrl": "https://en.wikipedia.org/wiki/Public_domain", "source": "https://commons.wikimedia.org/wiki/File:Alhambra_in_the_evening.jpg"}, {"id": "g-amer", "image": "places/g-amer.jpg", "level": 0, "country": "India", "title": "A fort on the hills", "alt": "A honey-coloured hilltop fort palace around a big courtyard full of visitors, with walls snaking over the hills behind.", "clue": "A hilltop fort palace of honey-coloured stone above a lake, near the 'Pink City', where elephants once carried visitors up.", "story": "Amer Fort near Jaipur was built from 1592 by Raja Man Singh. Inside is the Sheesh Mahal, a hall covered in thousands of tiny mirrors.", "credit": "Jakub Hałun / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Amber_Fort,_Jaipur,_20191219_1011_9509.jpg"}, {"id": "g-angkor", "image": "places/g-angkor.jpg", "level": 0, "country": "Cambodia", "title": "Temple towers at sunrise", "alt": "Silhouettes of temple towers and palm trees at sunrise, reflected in a still pond.", "clue": "The largest religious monument in the world, first built as a Hindu temple in the 1100s.", "story": "Angkor Wat was built by the Khmer king Suryavarman II in the 1100s. Its towers appear on the country's national flag.", "credit": "Martaapue / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Angkor_Wat_in_Cambodia.jpg"}, {"id": "g-arc", "image": "places/g-arc.jpg", "level": 0, "country": "France", "title": "A triumphal arch", "alt": "A massive carved stone arch lit up at dusk, with a slim iron tower glowing in the distance.", "clue": "A triumphal arch at the meeting of twelve avenues, with an unknown soldier's tomb and an eternal flame beneath it.", "story": "The Arc de Triomphe in Paris was finished in 1836. A flame for the Unknown Soldier has burned under it since 1923.", "credit": "Wilfredo Rafael Rodriguez Hernandez / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Arc_de_Triomphe_de_l%27%C3%89toile_at_night_vertical_fix.jpg"}, {"id": "g-atomium", "image": "places/g-atomium.jpg", "level": 0, "country": "Belgium", "title": "A giant atom", "alt": "Shiny metal spheres joined by tubes like a giant model of an atom, lit up with little lights against a dusky sky.", "clue": "A building shaped like an iron crystal magnified billions of times, made for a world's fair.", "story": "The Atomium in Brussels was built for the 1958 World's Fair. Visitors ride escalators through its tubes between the spheres.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Atomium,_Bruselas,_B%C3%A9lgica,_2021-12-15,_DD_148-150_HDR.jpg"}, {"id": "g-azadi", "image": "places/g-azadi.jpg", "level": 0, "country": "Iran", "title": "A tower of freedom", "alt": "A tall white marble tower with a curved arch and a honeycomb pattern, seen from below against a black night sky.", "clue": "A marble gateway tower whose name means freedom, mixing old Persian arches with modern shapes.", "story": "The Azadi Tower in Tehran was built in 1971. Its design draws on Persian architecture from before and after the coming of Islam.", "credit": "بهادر های زاده / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Azadi_Tower_at_night_in_low_angle.jpg"}, {"id": "g-basil", "image": "places/g-basil.jpg", "level": 0, "country": "Russia", "title": "Red walls and onion domes", "alt": "Red brick towers topped with stars, colourful onion domes and a large square in a big city.", "clue": "Red brick walls, ruby stars and a famous square whose name means 'beautiful'.", "story": "Red Square in Moscow sits beside the Kremlin. St Basil's Cathedral, with its swirling onion domes, was finished in 1561.", "credit": "Олег Токарев / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:%D0%92%D0%B8%D0%B4_%D0%BD%D0%B0_%D0%98%D1%81%D1%82%D0%BE%D1%80%D0%B8%D1%87%D0%B5%D1%81%D0%BA%D0%B8%D0%B9_%D0%BC%D1%83%D0%B7%D0%B5%D0%B9_%D0%B2_%D1%81%D1%82%D0%BE%D1%80%D0%BE%D0%BD%D1%83_%D0%9A%D1%80%D0%B0%D1%81%D0%BD%D0%BE%D0%B9_%D0%BF%D0%BB%D0%BE%D1%89%D0%B0%D0%B4%D0%B8.jpg"}, {"id": "g-belem", "image": "places/g-belem.jpg", "level": 0, "country": "Portugal", "title": "A tower in the river", "alt": "A white stone tower with little domed turrets, standing in a wide river and reached by a wooden walkway.", "clue": "A white tower that guarded the river mouth where the great ocean voyages of discovery set out.", "story": "The Belém Tower in Lisbon was built around 1519. Explorers sailed past it on their way to the ocean.", "credit": "Norbert Nagel / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Torre_de_Bel%C3%A9m_and_wooden_bridge_-_landscape_view_-_Lisbon_-_2026-05-14.jpg"}, {"id": "g-bigben", "image": "places/g-bigben.jpg", "level": 0, "country": "United Kingdom", "title": "A clock tower at dusk", "alt": "A gothic palace and a tall clock tower glowing gold beside a river at dusk.", "clue": "The great bell inside the clock tower has a nickname that everyone uses for the whole tower.", "story": "The Palace of Westminster in London is home to Parliament. Big Ben is really the name of the great bell inside the Elizabeth Tower.", "credit": "Diliff / Wikimedia Commons", "licence": "CC BY-SA 2.5", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.5/", "source": "https://commons.wikimedia.org/wiki/File:Palace_of_Westminster,_London_-_Feb_2007.jpg"}, {"id": "g-bluemosque", "image": "places/g-bluemosque.jpg", "level": 0, "country": "Turkey", "title": "A courtyard at dusk", "alt": "A great mosque with cascading domes and slender minarets, glowing gold at dusk behind an arcaded marble courtyard.", "clue": "A mosque with six minarets, named for the blue tiles inside, facing a great domed church-turned-museum across a park.", "story": "The Sultan Ahmed Mosque in Istanbul, known as the Blue Mosque, was finished in 1616. More than 20,000 hand-made tiles line its walls inside.", "credit": "Benh LIEU SONG (Flickr) / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Blue_Mosque_Courtyard_Dusk_Wikimedia_Commons.jpg"}, {"id": "g-borobudur", "image": "places/g-borobudur.jpg", "level": 0, "country": "Indonesia", "title": "A temple mountain", "alt": "A vast stepped stone temple with a bell-shaped stupa on top, on a green lawn.", "clue": "The largest Buddhist temple in the world, hidden under volcanic ash and jungle for centuries.", "story": "Borobudur in Central Java was built in the 800s. Its walls carry more than 2,600 carved relief panels.", "credit": "Jakub Hałun / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Borobudur,_Java,_Indonesia,_20220817_1013_8739.jpg"}, {"id": "g-brandenburg", "image": "places/g-brandenburg.jpg", "level": 0, "country": "Germany", "title": "A gate with a chariot", "alt": "A grand sandstone gate of tall columns, topped by a bronze statue of a goddess driving a four-horse chariot.", "clue": "A city gate topped by a four-horse chariot, which stood beside a wall that divided the city for 28 years.", "story": "The Brandenburg Gate in Berlin was finished in 1791. When the Berlin Wall fell in 1989, crowds gathered here to celebrate.", "credit": "Der Wolf im Wald/Author / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Brandenburger_Tor_morgens.jpg"}, {"id": "g-burj", "image": "places/g-burj.jpg", "level": 0, "country": "United Arab Emirates", "title": "The tallest tower", "alt": "A needle-thin skyscraper soaring above a hazy skyline across the water.", "clue": "The tallest building in the world rises from a desert city on the Persian Gulf.", "story": "The Burj Khalifa in Dubai is 828 metres tall and opened in 2010. On a clear day its tip can be seen from 95 kilometres away.", "credit": "Jpbowen / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Burj_Khalifa_from_the_sea,_Dubai.jpg"}, {"id": "g-charles", "image": "places/g-charles.jpg", "level": 0, "country": "Czech Republic", "title": "A river of bridges", "alt": "Stone bridges crossing a river through a city of red roofs, spires and autumn trees.", "clue": "A medieval stone bridge lined with statues crosses this river in the 'city of a hundred spires'.", "story": "The Vltava flows through Prague under a string of bridges. The oldest, Charles Bridge, was begun in 1357 and is lined with thirty statues.", "credit": "Dmitry A. Mottl / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Vltava_river_in_Prague.jpg"}, {"id": "g-charminar", "image": "places/g-charminar.jpg", "level": 0, "country": "India", "title": "Four minarets over the old city", "alt": "A square stone monument with four tall minarets, seen from above in the middle of a busy old city, with a large mosque nearby.", "clue": "A square monument with four minarets at the heart of an old city famous for pearls and biryani.", "story": "The Charminar in Hyderabad was built in 1591. Its name means 'four minarets', and the bustling Laad Bazaar of bangles spreads out around it.", "credit": "iMahesh / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Aerial_view_of_Charminar_and_its_locality.jpg"}, {"id": "g-chichen", "image": "places/g-chichen.jpg", "level": 0, "country": "Mexico", "title": "A stepped pyramid", "alt": "A stepped stone pyramid with a temple on top, on a wide lawn under white clouds.", "clue": "At the equinoxes, shadows make a serpent appear to slide down its staircase.", "story": "El Castillo at Chichén Itzá was built by the Maya. Its four staircases have 91 steps each, which with the top platform add up to 365, one for every day of the year.", "credit": "Daniel Schwen / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Chichen_Itza_2.jpg"}, {"id": "g-cntower", "image": "places/g-cntower.jpg", "level": 0, "country": "Canada", "title": "A needle by the lake", "alt": "A tall concrete tower with a pod near the top, beside a lake, skyscrapers and a white boat.", "clue": "A tall communications tower on the shore of one of the Great Lakes.", "story": "The CN Tower in Toronto, finished in 1976, was the world's tallest free-standing structure for 32 years. Visitors can walk around the outside edge, harnessed, 356 metres up.", "credit": "Maksim Sokolov (maxergon.com) / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Toronto_skyline_as_viewed_from_Ireland_Park.jpg"}, {"id": "g-colosseum", "image": "places/g-colosseum.jpg", "level": 0, "country": "Italy", "title": "An ancient arena", "alt": "A huge oval stone amphitheatre with arched tiers, beside ruined columns and tall cypress trees.", "clue": "Gladiators once fought here in front of up to 50,000 spectators, almost 2,000 years ago.", "story": "The Colosseum in Rome opened in 80 AD. It could hold around 50,000 people, and engineers could even flood the arena for mock sea battles.", "credit": "Wilfredo Rafael Rodriguez Hernandez / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Colosseum_of_Rome_and_Roman_forum.jpg"}, {"id": "g-edinburgh", "image": "places/g-edinburgh.jpg", "level": 0, "country": "United Kingdom", "title": "A castle on a rock", "alt": "A stone castle along the top of a steep volcanic crag, above green gardens where people sit on the grass.", "clue": "A castle on the plug of an old volcano, above gardens in a city that hosts a huge arts festival every August.", "story": "Edinburgh Castle in Scotland sits on Castle Rock, the core of a volcano that died out about 350 million years ago. A cannon is fired from it at one o'clock most days.", "credit": "Matti Blume / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Castle,_City_of_Edinburgh_(IMG_20190628_180330).jpg"}, {"id": "g-eiffel", "image": "places/g-eiffel.jpg", "level": 0, "country": "France", "title": "A wrought-iron tower in spring", "alt": "A tall lattice iron tower framed by blossoming trees under a blue sky.", "clue": "An iron lattice tower built for a world's fair in 1889 and once meant to be temporary.", "story": "The Eiffel Tower in Paris was built by Gustave Eiffel's company for the 1889 World's Fair. Critics called it an eyesore; it became the most visited paid monument in the world.", "credit": "Jorge Royan / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Paris_-_The_Eiffel_Tower_in_spring_-_2307.jpg"}, {"id": "g-eljem", "image": "places/g-eljem.jpg", "level": 0, "country": "Tunisia", "title": "An arena in a small town", "alt": "A huge oval stone arena with rows of arches, seen from the air in the middle of a town of low, pale houses.", "clue": "One of the largest Roman arenas ever built, standing in a small North African town that grew up around it.", "story": "The amphitheatre of El Jem in Tunisia was built around 238 AD and could seat about 35,000 people. It is among the best preserved Roman ruins anywhere.", "credit": "Skander zarrad / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Amphith%C3%A9%C3%A2tre_d%E2%80%99El_Jem_vue_aerienne_(2023)_1.jpg"}, {"id": "g-everest", "image": "places/g-everest.jpg", "level": 0, "country": "Nepal", "title": "The highest peak at sunset", "alt": "Snowy mountain peaks under a deep violet sky, with the tallest summit glowing red in the last sunlight.", "clue": "The highest mountain on Earth, seen from the trekking trails on its southern side, home of the Sherpa people.", "story": "Mount Everest stands 8,849 metres tall on the border of Nepal and China. Locally it is called Sagarmatha and Chomolungma.", "credit": "Nir B. Gurung / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Sunset_view_of_Everest.jpg"}, {"id": "g-florence", "image": "places/g-florence.jpg", "level": 0, "country": "Italy", "title": "A red dome at dusk", "alt": "A cathedral with a vast red-brick dome and a striped bell tower rising over a city of terracotta roofs, with hills behind.", "clue": "The biggest brick dome ever built, in the city where the Renaissance began.", "story": "Florence Cathedral's dome was designed by Filippo Brunelleschi and finished in 1436. Climbing its 463 steps takes you between its inner and outer shells.", "credit": "Dllu / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Florence_Cathedral_seen_from_Piazzale_Michelangelo_night_dllu.jpg"}, {"id": "g-forbidden", "image": "places/g-forbidden.jpg", "level": 0, "country": "China", "title": "Golden roofs of a palace city", "alt": "Rows of palace halls with golden-yellow tiled roofs and red walls, stretching towards a modern city skyline.", "clue": "Nearly a thousand golden-roofed buildings where emperors lived for five centuries.", "story": "The Forbidden City in Beijing was the home of China's emperors from 1420 to 1912. Yellow roof tiles were kept for the emperor alone; today it is the Palace Museum.", "credit": "Güldem Üstün from Istanbul, TURKEY / Wikimedia Commons", "licence": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "source": "https://commons.wikimedia.org/wiki/File:China_(Beijing)_Aerial_view_of_Forbidden_City_(38884882275).jpg"}, {"id": "g-fuji", "image": "places/g-fuji.jpg", "level": 0, "country": "Japan", "title": "A pagoda and a snowy volcano", "alt": "A red five-storey pagoda in front of a snow-capped volcano above a city.", "clue": "A perfectly shaped snow-topped volcano, a favourite subject of woodblock prints.", "story": "Mount Fuji, seen from the Chureito Pagoda, is the country's tallest mountain at 3,776 metres. It last erupted in 1707.", "credit": "Stjepko Krehula / Wikimedia Commons", "licence": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Chureito_Pagoda_and_Mount_Fuji_2023-03-07.jpg"}, {"id": "g-gateway", "image": "places/g-gateway.jpg", "level": 0, "country": "India", "title": "An arch by the harbour", "alt": "A grand stone arch on a waterfront, beside a hotel with a red dome and a tall tower, with ferries bobbing in front.", "clue": "A waterfront arch built to welcome a visiting king and queen, beside a famous red-domed hotel on the Arabian Sea.", "story": "The Gateway of India in Mumbai was finished in 1924. Ferries leave from its steps for the cave temples of Elephanta Island.", "credit": "iMahesh / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Panoramic_view_of_Taj_Palace_Hotel_and_Taj_Tower_with_the_iconic_Gateway_of_India_in_the_background.jpg"}, {"id": "g-giza", "image": "places/g-giza.jpg", "level": 0, "country": "Egypt", "title": "Pyramids in the desert", "alt": "Three great stone pyramids rising from golden sand under a clear sky.", "clue": "The largest was the tallest human-made structure on Earth for nearly 4,000 years.", "story": "The Pyramids of Giza were built around 4,500 years ago as tombs for pharaohs. The Great Pyramid is the only one of the Seven Wonders of the Ancient World still standing.", "credit": "Ricardo Liberato / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:All_Gizah_Pyramids.jpg"}, {"id": "g-goldengate", "image": "places/g-goldengate.jpg", "level": 0, "country": "United States", "title": "An orange bridge in the mist", "alt": "A red-orange suspension bridge over a strait, seen from a rocky beach with misty water and boulders.", "clue": "A suspension bridge painted \"International Orange\", spanning a foggy strait where a bay meets the Pacific.", "story": "The Golden Gate Bridge in San Francisco opened in 1937. Its orange colour was chosen to stand out in the fog, and painters touch it up all year round.", "credit": "Frank Schulenburg / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Golden_Gate_Bridge_as_seen_from_Marshall%E2%80%99s_Beach,_March_2018.jpg"}, {"id": "g-goldentemple", "image": "places/g-goldentemple.jpg", "level": 0, "country": "India", "title": "A golden temple on a pool", "alt": "A gilded temple in the middle of a still pool, with white marble walkways and a barefoot pilgrim in a white turban.", "clue": "A gilded shrine in a sacred pool, whose free community kitchen feeds tens of thousands of visitors every day.", "story": "The Harmandir Sahib, or Golden Temple, in Amritsar is the holiest shrine of the Sikh faith. Its langar kitchen serves a free meal to anyone who comes, every day of the year.", "credit": "Paulrudd / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Sikh_pilgrim_at_the_Golden_Temple_(Harmandir_Sahib)_in_Amritsar,_India.jpg"}, {"id": "g-grandcanyon", "image": "places/g-grandcanyon.jpg", "level": 0, "country": "United States", "title": "A canyon of red layers", "alt": "A vast canyon of red, orange and purple rock layers stretching to the horizon, with clouds and a faint rainbow above.", "clue": "A canyon more than a kilometre and a half deep, carved by a river over millions of years in a dry south-western state.", "story": "The Grand Canyon in Arizona was carved by the Colorado River. Its lowest rocks are nearly two billion years old.", "credit": "Tuxyso / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Grand_Canyon_Hopi_Point_with_rainbow_2013.jpg"}, {"id": "g-grandpalace", "image": "places/g-grandpalace.jpg", "level": 0, "country": "Thailand", "title": "Golden spires by a white wall", "alt": "Golden spires and tiled temple roofs behind a long white wall, mirrored in a puddle, as a monk in a saffron robe walks past.", "clue": "A royal palace and temple of glittering spires, home to a small, much-loved statue of the Buddha carved from green stone.", "story": "The Grand Palace in Bangkok was built from 1782. Inside its walls stands the Temple of the Emerald Buddha, the most sacred temple in Thailand.", "credit": "Nawit science / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Temple_of_the_Emerald_Buddha.jpg"}, {"id": "g-greatwall", "image": "places/g-greatwall.jpg", "level": 0, "country": "China", "title": "A wall across the mountains", "alt": "A stone wall with watchtowers winding along green mountain ridges.", "clue": "Built and rebuilt over many dynasties to guard a northern frontier.", "story": "The Great Wall of China stretches thousands of kilometres. This is the Mutianyu section near Beijing, rebuilt during the Ming dynasty in the 1500s.", "credit": "Velatrix / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Great_Wall_of_China_July_2006.JPG"}, {"id": "g-guggenheim", "image": "places/g-guggenheim.jpg", "level": 0, "country": "Spain", "title": "A museum of silver curves", "alt": "A museum of swooping, shining metal curves beside a river, with a red arch bridge and a giant flower-like sculpture nearby.", "clue": "A museum covered in curving titanium panels, which turned a northern industrial port into an art destination.", "story": "The Guggenheim Museum Bilbao, designed by Frank Gehry, opened in 1997. Its walls are clad in about 33,000 thin sheets of titanium.", "credit": "José Ligero Loarte / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Museo_Guggenheim_--_2021_--_Bilbao,_Euskadi,_Espa%C3%B1a.jpg"}, {"id": "g-gyeongbok", "image": "places/g-gyeongbok.jpg", "level": 0, "country": "South Korea", "title": "A pavilion on a pond", "alt": "A wooden pavilion with a curved tiled roof standing on stone pillars over a still pond.", "clue": "A royal palace pavilion where kings held banquets, in a capital surrounded by mountains.", "story": "Gyeongbokgung in Seoul was the main royal palace of the Joseon dynasty from 1395. The Gyeonghoeru pavilion stands on 48 stone pillars.", "credit": "Frank Schulenburg / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Gyeonghoeru_(Royal_Banquet_Hall)_at_Gyeongbokgung_Palace,_Seoul.jpg"}, {"id": "g-hagia", "image": "places/g-hagia.jpg", "level": 0, "country": "Turkey", "title": "Domes and minarets", "alt": "A great domed building in pink and grey stone, with four tall minarets.", "clue": "Built as a cathedral, later a mosque, its huge dome seemed to float to those who first saw it.", "story": "Hagia Sophia in Istanbul was completed in 537. For nearly a thousand years it had the largest dome in the world.", "credit": "Arild Vågen / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Hagia_Sophia_Mars_2013.jpg"}, {"id": "g-harbourbridge", "image": "places/g-harbourbridge.jpg", "level": 0, "country": "Australia", "title": "A steel arch at night", "alt": "A huge steel arch bridge lit up at night over a harbour, with stone pylons at each end and city lights behind.", "clue": "A steel arch bridge nicknamed 'the Coathanger', near a famous opera house with roofs like sails.", "story": "The Sydney Harbour Bridge opened in 1932. Visitors can climb over the top of its arch, 134 metres above the water.", "credit": "JJ Harrison (https://www.jjharrison.com.au/) / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Sydney_Harbour_Bridge_from_Circular_Quay.jpg"}, {"id": "g-hassan", "image": "places/g-hassan.jpg", "level": 0, "country": "Morocco", "title": "A minaret by the ocean", "alt": "A very tall square minaret covered in green and cream tilework, framed by a carved archway in warm evening light.", "clue": "A mosque with one of the tallest minarets in the world, built partly over the Atlantic Ocean in a big port city.", "story": "The Hassan II Mosque in Casablanca was finished in 1993. Its minaret rises 210 metres, and part of the prayer hall has a glass floor over the sea.", "credit": "OussamaHamama / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Whispers_of_Gold_-_Hassan_II_Mosque_at_Dusk.jpg"}, {"id": "g-himeji", "image": "places/g-himeji.jpg", "level": 0, "country": "Japan", "title": "A white castle", "alt": "A white castle of stacked curved roofs rising above trees and a stone wall reflected in a moat.", "clue": "A brilliant white castle nicknamed the White Heron, which survived wars and earthquakes for over 400 years.", "story": "Himeji Castle in Japan was finished in its present form in 1609. Its white plaster walls helped protect the wooden building from fire.", "credit": "Martin Falbisoner / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Himeji_Castle,_November_2016_-02.jpg"}, {"id": "g-humayun", "image": "places/g-humayun.jpg", "level": 0, "country": "India", "title": "A garden tomb", "alt": "A red sandstone tomb with a white marble dome, at the end of a long water channel in a formal garden.", "clue": "A garden tomb for a Mughal emperor, built decades before a more famous marble one and an inspiration for it.", "story": "Humayun's Tomb in Delhi was finished in 1570, commissioned by the emperor's widow, Bega Begum. It was the first great garden tomb of its kind.", "credit": "Jakub Hałun / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:20191205_Grobowiec_Humajuna_w_Delhi_1055_6794.jpg"}, {"id": "g-itsukushima", "image": "places/g-itsukushima.jpg", "level": 0, "country": "Japan", "title": "A gate in the sea", "alt": "A huge red wooden gate standing in calm blue sea water, with green wooded hills behind.", "clue": "A giant red shrine gate that seems to float on the sea at high tide, on a sacred island where deer roam free.", "story": "The great torii of Itsukushima Shrine on Miyajima, Japan, stands in the sea by its own weight. At low tide visitors can walk out to it.", "credit": "JordyMeow / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Itsukushima_Gate.jpg"}, {"id": "g-karnak", "image": "places/g-karnak.jpg", "level": 0, "country": "Egypt", "title": "An avenue of rams", "alt": "A row of stone sphinxes with rams' heads, each guarding a small statue of a king, in front of massive sandstone walls.", "clue": "A vast temple complex of giant columns and ram-headed sphinxes beside the Nile, on the site of an ancient capital.", "story": "The Karnak temple complex at Luxor in Egypt was added to by kings over about 2,000 years. Its great hall holds 134 huge columns.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Templo_de_Karnak,_Luxor,_Egipto,_2022-04-03,_DD_144.jpg"}, {"id": "g-kilimanjaro", "image": "places/g-kilimanjaro.jpg", "level": 0, "country": "Tanzania", "title": "Snow above the savanna", "alt": "A snow-capped mountain floating above a band of cloud, with flat-topped acacia trees on a dry plain below.", "clue": "The roof of a continent: a lone snow-capped volcano rising almost 6,000 metres above the savanna.", "story": "Mount Kilimanjaro in Tanzania is the highest mountain in Africa, 5,895 metres high. This photo was taken from Amboseli National Park, just over the border in Kenya, which has some of the best views of the peak.", "credit": "Sergey Pesterev / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Kilimanjaro_from_Amboseli.jpg"}, {"id": "g-kinderdijk", "image": "places/g-kinderdijk.jpg", "level": 0, "country": "Netherlands", "title": "Windmills on the water", "alt": "Old brick windmills along a reedy canal with water lilies.", "clue": "Nineteen windmills that pumped water out of land lying below sea level.", "story": "The windmills of Kinderdijk were built around 1740 to drain the polders. They are a UNESCO World Heritage Site.", "credit": "Tarod / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:The_windmills_of_Kinderdijk.JPG"}, {"id": "g-kinkakuji", "image": "places/g-kinkakuji.jpg", "level": 0, "country": "Japan", "title": "A golden pavilion", "alt": "A pavilion covered in gold leaf beside a still pond with pine-covered islands, mirrored in the water.", "clue": "A pavilion covered in gold leaf, beside a mirror pond, in a city of a thousand temples.", "story": "Kinkaku-ji, the Golden Pavilion, is a Zen temple in Kyoto. The building was rebuilt in 1955 after a fire, and its gold was renewed in the 1980s.", "credit": "Basile Morin / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Water_reflection_of_Kinkaku-ji_Temple_a_sunny_day,_Kyoto,_Japan.jpg"}, {"id": "g-konark", "image": "places/g-konark.jpg", "level": 0, "country": "India", "title": "A stone chariot wheel", "alt": "A huge carved stone wheel with eight wide spokes, set into a temple wall covered in small carved figures.", "clue": "One of 24 carved wheels on a temple built as the chariot of the sun god, near the eastern coast.", "story": "The Konark Sun Temple in Odisha was built in the 13th century as a giant stone chariot. Its wheels work as sundials, and one appears on the ten-rupee note.", "credit": "Joydeep / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Wheel_engraved_in_the_13th_century_built_Konark_Sun_Temple_in_Orissa,_India.jpg"}, {"id": "g-lalibela", "image": "places/g-lalibela.jpg", "level": 0, "country": "Ethiopia", "title": "A church cut into the rock", "alt": "A cross-shaped church carved down into solid red rock, standing in a deep pit at sunset, with hills behind.", "clue": "A church carved downwards from a single block of rock, shaped like a cross, in the highlands of the Horn of Africa.", "story": "The Church of Saint George in Lalibela, Ethiopia, was cut out of the rock about 800 years ago. Lalibela has eleven such churches, still used for worship.", "credit": "Thomas Fuhrmann / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Ethiopia_-_sunset_at_Church_of_Saint_George,_Lalibela_01.jpg"}, {"id": "g-liberty", "image": "places/g-liberty.jpg", "level": 0, "country": "United States", "title": "A copper lady with a torch", "alt": "A green statue holding a torch high on an island, with a city skyline and a tour boat behind.", "clue": "A gift from France in 1886, turned green as its copper skin weathered.", "story": "The Statue of Liberty stands in New York Harbor. Its copper turned green over about 30 years, and it welcomed millions of immigrants arriving by ship.", "credit": "Christian David / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Statue_of_Liberty_and_a_sightseeing_boat,_Liberty_Island,_New_York.jpg"}, {"id": "g-lincoln", "image": "places/g-lincoln.jpg", "level": 0, "country": "United States", "title": "A temple to a president", "alt": "A white marble building like a Greek temple, with a row of tall columns at the top of wide steps, under a blue sky.", "clue": "A marble memorial with 36 columns, one for each state in the union when the president it honours died.", "story": "The Lincoln Memorial in Washington, D.C., opened in 1922. Martin Luther King Jr. gave his 'I Have a Dream' speech on its steps in 1963.", "credit": "Martin Falbisoner / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Lincoln_Memorial_east_side.JPG"}, {"id": "g-lotus", "image": "places/g-lotus.jpg", "level": 0, "country": "India", "title": "A temple like a flower", "alt": "A white building shaped like a half-open lotus flower, its marble petals rising above blue pools and visitors.", "clue": "A house of worship shaped like a lotus, open to people of every faith, in a capital city.", "story": "The Lotus Temple in Delhi is a Bahá'í house of worship, opened in 1986. Its 27 marble petals are arranged in clusters of three.", "credit": "Bijay chaurasia / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Lotus_Temple-Panoroma-Visit_During_WCI_2016-_IMG_6471.jpg"}, {"id": "g-louvre", "image": "places/g-louvre.jpg", "level": 0, "country": "France", "title": "A glass pyramid", "alt": "A glass pyramid glowing at dusk in a courtyard surrounded by grand old palace wings.", "clue": "A glass pyramid entrance in the courtyard of a royal palace that became the world's most visited art museum.", "story": "The Louvre in Paris was a royal palace before it became a museum in 1793. I. M. Pei's glass pyramid entrance opened in 1989.", "credit": "Benh LIEU SONG / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Cour_Napol%C3%A9on_at_night_-_Louvre.jpg"}, {"id": "g-machu", "image": "places/g-machu.jpg", "level": 0, "country": "Peru", "title": "A city in the clouds", "alt": "Stone ruins and green terraces on a mountain ridge, with a steep green peak rising behind.", "clue": "A 15th-century stone citadel on a high Andean ridge, made famous around the world in 1911.", "story": "Machu Picchu was built for the Inca emperor Pachacuti around 1450. The peak behind it is Huayna Picchu.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Machu_Picchu,_Per%C3%BA,_2015-07-30,_DD_47.JPG"}, {"id": "g-marina", "image": "places/g-marina.jpg", "level": 0, "country": "Singapore", "title": "A lotus by the bay", "alt": "A white lotus-shaped museum in front of glass towers along a waterfront.", "clue": "A city-state on an island, where a lotus-shaped museum sits beside a famous hotel with a 'ship' on its roof.", "story": "The ArtScience Museum at Marina Bay in Singapore opened in 2011. Its roof collects rainwater that runs down through its centre.", "credit": "Basile Morin / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:ArtScience_Museum,_Marina_Bay_Sands,_Singapore.jpg"}, {"id": "g-meenakshi", "image": "places/g-meenakshi.jpg", "level": 0, "country": "India", "title": "A tower of a thousand figures", "alt": "A towering temple gateway covered from base to top in brightly painted sculptures of gods and animals, against a blue sky.", "clue": "One of fourteen towering temple gateways covered in painted gods, in an ancient southern city on the Vaigai river.", "story": "The Meenakshi Amman Temple in Madurai is dedicated to the goddess Meenakshi. Its tallest gateway tower is about 52 metres high, and the figures are repainted every few years.", "credit": "MADHURANTHAKAN JAGADEESAN / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:S-TN-34_Meenakshi_Amman_Temple_South_Gopuram_enriched_with_delicate_Stucco_works.jpg"}, {"id": "g-meteora", "image": "places/g-meteora.jpg", "level": 0, "country": "Greece", "title": "A monastery on a rock", "alt": "A monastery with red tiled roofs perched on top of a sheer rock pillar, among wooded cliffs.", "clue": "Monasteries perched on giant rock pillars, once reached only by ladders and baskets pulled up on ropes.", "story": "Meteora in Greece means 'suspended in the air'. Monks built these monasteries from the 14th century, and six are still lived in.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Roussanou_Monastery,_Meteora.jpg"}, {"id": "g-mezquita", "image": "places/g-mezquita.jpg", "level": 0, "country": "Spain", "title": "A mosque and a bridge", "alt": "A long stone bridge of many arches crossing a shallow green river towards a great golden building with a bell tower.", "clue": "A vast old mosque with a cathedral built inside it, beside a Roman bridge in a southern city once ruled by the Moors.", "story": "The Mosque-Cathedral of Córdoba was begun in 785 and has a forest of more than 800 columns. A cathedral was built in its centre in the 16th century.", "credit": "Jose María Ligero Loarte / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Centro_Hist%C3%B3rico,_16.9_--_2023_--_C%C3%B3rdoba,_Espa%C3%B1a.jpg"}, {"id": "g-milford", "image": "places/g-milford.jpg", "level": 0, "country": "New Zealand", "title": "A peak above the fiord", "alt": "A sharp mountain peak rising from a fiord between steep green cliffs.", "clue": "A fiord in the far south-west of two large islands, where the film trilogy about a ring was shot nearby.", "story": "Milford Sound in Fiordland was carved by glaciers. Mitre Peak rises 1,692 metres straight out of the water.", "credit": "Krzysztof Golik / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Milford_Sound_in_Fiordland_National_Park_08.jpg"}, {"id": "g-moai", "image": "places/g-moai.jpg", "level": 0, "country": "Chile", "title": "A row of stone heads", "alt": "A long row of giant stone statues with large heads standing on a platform beyond tall grass.", "clue": "Nearly a thousand giant stone figures on a remote Pacific island, far from any other land.", "story": "These are the fifteen moai of Ahu Tongariki on Easter Island (Rapa Nui), which belongs to Chile. They were re-erected in the 1990s after a tsunami had scattered them.", "credit": "Phil Whitehouse from London, United Kingdom / Wikimedia Commons", "licence": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Row_(2051934571).jpg"}, {"id": "g-montstmichel", "image": "places/g-montstmichel.jpg", "level": 0, "country": "France", "title": "An island abbey and its sheep", "alt": "A rocky island crowned by an abbey with a tall spire, beyond green meadows where sheep are grazing.", "clue": "An abbey-topped island that becomes part of the mainland when the tide goes out, with sheep on the salt meadows.", "story": "Mont-Saint-Michel stands in a bay on the coast of Normandy, France. Its tides are among the strongest in Europe, and lamb raised on the salt meadows is a local speciality.", "credit": "Eric Kilby / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Mont_Saint_Michel_and_sheep_-_2026.jpg"}, {"id": "g-neuschwanstein", "image": "places/g-neuschwanstein.jpg", "level": 0, "country": "Germany", "title": "A fairy-tale castle", "alt": "A white castle with slender turrets perched on a forested hillside.", "clue": "A romantic king's castle in the Bavarian Alps, said to have inspired a famous fairy-tale castle at a theme park.", "story": "Neuschwanstein Castle was built for King Ludwig II from 1869. He lived there for only a few months, and it opened to visitors soon after his death.", "credit": "Wilfredo Rafael Rodriguez Hernandez / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Neuschwanstein_Castle_2024.jpg"}, {"id": "g-niagara", "image": "places/g-niagara.jpg", "level": 0, "country": "Canada", "title": "A horseshoe of water", "alt": "A wide curved waterfall throwing up clouds of mist, with a rainbow and a small tour boat in the green water below.", "clue": "A horseshoe-shaped waterfall on a border river between two great lakes, visited by boats that sail right into the spray.", "story": "The Horseshoe Falls at Niagara are mostly on the Canadian side of the border. Boats have carried visitors into the mist since 1846.", "credit": "DXR / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Maid_of_the_Mist_VII_approaching_the_Horseshoe_Falls,_West_view_20170418_1.jpg"}, {"id": "g-opera", "image": "places/g-opera.jpg", "level": 0, "country": "Australia", "title": "Sails on the harbour", "alt": "A white building with roofs shaped like sails, lit up at night beside dark water and a city skyline.", "clue": "Its roof shells were designed by a Danish architect after a competition in 1957.", "story": "The Sydney Opera House, designed by Jørn Utzon, opened in 1973. More than a million roof tiles cover its famous shells.", "credit": "Diliff / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Sydney_Opera_House_-_Dec_2008.jpg"}, {"id": "g-pamukkale", "image": "places/g-pamukkale.jpg", "level": 0, "country": "Turkey", "title": "White terraces", "alt": "Snow-white stone terraces with shallow pools of water stepping down a hillside, with visitors walking barefoot along the top.", "clue": "Hot springs that left white mineral terraces down a hillside, beside the ruins of an ancient Greek spa city.", "story": "Pamukkale means 'cotton castle' in Turkish. The terraces are made of travertine left by warm, mineral-rich spring water over thousands of years.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Pamukkale_02.jpg"}, {"id": "g-pantheon", "image": "places/g-pantheon.jpg", "level": 0, "country": "Italy", "title": "An open eye in a dome", "alt": "Looking straight up into a huge coffered concrete dome with a round opening to the sky at its centre.", "clue": "An ancient temple whose great concrete dome, with a round opening at the top, is still the largest unreinforced one in the world.", "story": "The Pantheon in Rome was finished around 125 AD. Rain falls through the oculus in its dome and drains away through small holes in the floor.", "credit": "Livioandronico2013 / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Dome_of_Pantheon_(Rome).jpg"}, {"id": "g-parkguell", "image": "places/g-parkguell.jpg", "level": 0, "country": "Spain", "title": "Gingerbread houses", "alt": "Two fairy-tale houses with wavy white roofs and a tower covered in blue and white tiles, above a crowded entrance and a city stretching to the sea.", "clue": "A hillside park of wavy tiled buildings by the same architect as a famous unfinished basilica in the same city.", "story": "Park Güell in Barcelona was designed by Antoni Gaudí and opened to the public in 1926. Its famous long bench is covered in broken tile mosaic.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Park_G%C3%BCell_02.jpg"}, {"id": "g-perito", "image": "places/g-perito.jpg", "level": 0, "country": "Argentina", "title": "A wall of blue ice", "alt": "A towering wall of blue-white ice meeting a lake, with snowy mountains behind.", "clue": "A glacier that has stayed roughly the same size for a century, in a windswept region at the bottom of a continent.", "story": "The Perito Moreno Glacier in Patagonia is about 30 km long. Huge chunks of ice regularly break off its face with a roar.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Glaciar_Perito_Moreno14_-_Argentina.JPG"}, {"id": "g-petra", "image": "places/g-petra.jpg", "level": 0, "country": "Jordan", "title": "Camels at the Treasury", "alt": "Camels with colourful saddles in front of a grand temple-like facade carved into rose-red rock.", "clue": "A 'rose-red city' carved straight into desert cliffs by Nabataean traders over 2,000 years ago.", "story": "Al-Khazneh, the Treasury, is the most famous building in Petra, Jordan. It is not built but carved directly into the sandstone cliff.", "credit": "Tareq Mnadili / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Petra_city_22.jpg"}, {"id": "g-petronas", "image": "places/g-petronas.jpg", "level": 0, "country": "Malaysia", "title": "Twin silver towers", "alt": "Two identical silver skyscrapers joined by a sky bridge, among other towers and green trees.", "clue": "Twin towers whose floor plan is based on an eight-pointed star from Islamic art.", "story": "The Petronas Towers in Kuala Lumpur were the world's tallest buildings from 1998 to 2004. A double-deck sky bridge links them on the 41st and 42nd floors.", "credit": "CEphoto, Uwe Aranas / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Kuala_Lumpur_Malaysia_Skyline-03.jpg"}, {"id": "g-pisa", "image": "places/g-pisa.jpg", "level": 0, "country": "Italy", "title": "A tower that leans", "alt": "A white marble cathedral on a green lawn, with a leaning bell tower behind it and the sun bursting beside it.", "clue": "A marble bell tower that began to tilt before it was even finished.", "story": "The Leaning Tower of Pisa in Italy is the bell tower of the cathedral beside it. Building started in 1173, and the soft ground made it lean; engineers have since made it safe without straightening it.", "credit": "MHoser / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:The_Duomo_and_Tower_of_Pisa_at_sunrise.jpg"}, {"id": "g-pompeii", "image": "places/g-pompeii.jpg", "level": 0, "country": "Italy", "title": "A town under the volcano", "alt": "Broken white stone columns and old brick ruins in a wide open square, with a mountain rising behind under white clouds.", "clue": "A Roman town buried in volcanic ash in a single day, with the volcano that did it still in view.", "story": "Pompeii, near Naples, was buried when Mount Vesuvius erupted in 79 AD. The ash preserved its streets, paintings and even loaves of bread.", "credit": "Commonists / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Forum_(Pompeii)_and_the_Vesuvio.jpg"}, {"id": "g-prambanan", "image": "places/g-prambanan.jpg", "level": 0, "country": "Indonesia", "title": "A cluster of stone spires", "alt": "Tall pointed temple towers of dark carved stone rising above fields of fallen blocks, under a blue sky with white clouds.", "clue": "Soaring Hindu temple spires built over a thousand years ago, not far from a great Buddhist monument on the same island.", "story": "Prambanan in Central Java was built in the 9th century for Shiva, Vishnu and Brahma. Its main temple is 47 metres tall.", "credit": "Jakub Hałun / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Prambanan_temple,_Central_Java,_Indonesia,_20220818_1311_9139.jpg"}, {"id": "g-redeemer", "image": "places/g-redeemer.jpg", "level": 0, "country": "Brazil", "title": "A statue above the clouds", "alt": "A statue with outstretched arms on a mountain peak, standing above a sea of clouds at sunrise.", "clue": "Arms wide open on a granite peak, looking over a city famous for its carnival.", "story": "Christ the Redeemer on Corcovado mountain above Rio de Janeiro was completed in 1931. It stands 30 metres tall and is often struck by lightning.", "credit": "Donatas Dabravolskas / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Redentor_Over_Clouds_1.jpg"}, {"id": "g-rushmore", "image": "places/g-rushmore.jpg", "level": 0, "country": "United States", "title": "Faces in the mountain", "alt": "Four giant faces of men carved into a granite cliff under a deep blue sky, with pine trees and rubble below.", "clue": "Four leaders' faces, each about 18 metres tall, carved into a granite mountain in the Black Hills.", "story": "Mount Rushmore in South Dakota was carved between 1927 and 1941. It shows presidents Washington, Jefferson, Theodore Roosevelt and Lincoln.", "credit": "Der Wolf im Wald/Author/Canon EOS 5DS / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Mount_Rushmore_detail_view_(100MP).jpg"}, {"id": "g-sagrada", "image": "places/g-sagrada.jpg", "level": 0, "country": "Spain", "title": "Towers among the cranes", "alt": "Looking up at intricate stone spires of a huge church surrounded by construction cranes.", "clue": "A basilica started in 1882 that is still being built, designed by an architect who loved curves and nature.", "story": "The Sagrada Família in Barcelona was Antoni Gaudí's life's work. Building has continued for more than 140 years.", "credit": "Mstyslav Chernov / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:View_of_Basilica_and_Expiatory_Church_of_the_Holy_Family_(Bas%C3%ADlica_i_Temple_Expiatori_de_la_Sagrada_Fam%C3%ADlia)_(_UNESCO_World_Heritage_Site)._Barcelona,_Catalonia,_Spain.jpg"}, {"id": "g-schonbrunn", "image": "places/g-schonbrunn.jpg", "level": 0, "country": "Austria", "title": "A summer palace", "alt": "A long yellow palace with formal gardens in front, seen from a hill over a city of red roofs.", "clue": "The summer palace of an empire's royal family, with a zoo in its garden that is the oldest in the world still open.", "story": "Schönbrunn Palace in Vienna has 1,441 rooms. Its zoo opened in 1752.", "credit": "Der Wolf im Wald/Author/Canon EOS 5D Mark II / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Schloss_Sch%C3%B6nbrunn_Wien_2014_(Zuschnitt_1).jpg"}, {"id": "g-sugarloaf", "image": "places/g-sugarloaf.jpg", "level": 0, "country": "Brazil", "title": "A cable car over the bay", "alt": "A glass cable car gliding over a wooded peak, high above a bay full of small boats and a city of tall buildings.", "clue": "A cable car up a granite peak at the mouth of a bay, in a city famous for its carnival and beaches.", "story": "The cable car up Sugarloaf Mountain in Rio de Janeiro opened in 1912. From the top you can see Copacabana beach and the Christ the Redeemer statue.", "credit": "Wilfredo Rafael Rodriguez Hernandez / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Sugarloaf_Cable_Car_viewed_from_Rio_de_Janeiro,_Brazil.jpg"}, {"id": "g-table", "image": "places/g-table.jpg", "level": 0, "country": "South Africa", "title": "A flat-topped mountain", "alt": "A city at dawn below a long, flat-topped mountain.", "clue": "A mountain with a top as flat as a table, above a harbour city near the southern tip of a continent.", "story": "Table Mountain rises above Cape Town in South Africa. When cloud spills over its flat top, locals say the 'tablecloth' is on.", "credit": "Daniel Case / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Cape_Town_City_Bowl_and_Table_Mountain_at_dawn.jpg"}, {"id": "g-taj", "image": "places/g-taj.jpg", "level": 0, "country": "India", "title": "A marble mausoleum", "alt": "A white marble domed tomb with four slender minarets, reflected in a long garden pool.", "clue": "A white marble tomb built by an emperor in memory of his wife, beside the Yamuna river.", "story": "The Taj Mahal in Agra was built by Mughal emperor Shah Jahan for Mumtaz Mahal, finished around 1653. Its marble changes colour from pink at dawn to gold at sunset.", "credit": "Yann; edited by Jim Carter / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Taj_Mahal_(Edited).jpeg"}, {"id": "g-tanahlot", "image": "places/g-tanahlot.jpg", "level": 0, "country": "Indonesia", "title": "A temple on a sea rock", "alt": "A small temple with thatched roofs on a rocky island in the surf, with visitors on the wet rocks in front.", "clue": "A sea temple on a rock that becomes an island at high tide, on a famous island of rice terraces and dancers.", "story": "Tanah Lot is one of the sea temples of Bali, built around the 16th century. Sea snakes living in the rocks are said to guard it.", "credit": "CEphoto, Uwe Aranas / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Tanah-Lot_Bali_Indonesia_Pura-Tanah-Lot-01.jpg"}, {"id": "g-templeheaven", "image": "places/g-templeheaven.jpg", "level": 0, "country": "China", "title": "A round hall of blue roofs", "alt": "A round wooden hall with three tiers of deep blue roofs and a golden top, on a white marble terrace with crowds below.", "clue": "A round hall with three blue roofs, where emperors prayed each year for a good harvest.", "story": "The Hall of Prayer for Good Harvests at the Temple of Heaven in Beijing is built of wood without a single nail. The blue roofs stand for the sky.", "credit": "Fong Chen / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Hall_of_Prayer_for_Good_Harvest.JPG"}, {"id": "g-teotihuacan", "image": "places/g-teotihuacan.jpg", "level": 0, "country": "Mexico", "title": "A city of pyramids", "alt": "A wide stepped stone pyramid at the end of a long avenue, with smaller platforms on either side and mountains beyond.", "clue": "An ancient city of great pyramids and a long avenue, built long before the Aztecs found it and named it 'the place of the gods'.", "story": "Teotihuacan, near Mexico City, was one of the largest cities in the world around 500 AD. The pyramid in this view is the Pyramid of the Moon.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Teotihuac%C3%A1n,_M%C3%A9xico,_2013-10-13,_DD_45.JPG"}, {"id": "g-terracotta", "image": "places/g-terracotta.jpg", "level": 0, "country": "China", "title": "An army of clay", "alt": "Rows of life-size clay soldiers and horses standing in an earthen pit, each face slightly different.", "clue": "Thousands of life-size clay soldiers buried to guard the tomb of the first emperor to unite a great land.", "story": "The Terracotta Army near Xi'an was found by farmers digging a well in 1974. More than 8,000 soldiers were made, and no two faces are alike.", "credit": "Gary Todd / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Qin_Shihuang_Terracotta_Army,_Pit_1_Warriors_%26_Horses.jpg"}, {"id": "g-torres", "image": "places/g-torres.jpg", "level": 0, "country": "Chile", "title": "Horns of granite", "alt": "Jagged mountain peaks of pale granite capped with dark rock and snow, rising above green hills under a bright sky.", "clue": "Granite peaks capped with dark rock like horns, in a national park near the southern tip of a long, thin country.", "story": "The Cuernos, or 'Horns', of Torres del Paine in Chilean Patagonia are pale granite capped with darker, older rock. Strong winds and guanacos are common on its trails.", "credit": "James St. John / Wikimedia Commons", "licence": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Cretaceous_sedimentary_rocks_intruded_by_a_Miocene_granite_laccolith.jpg"}, {"id": "g-trevi", "image": "places/g-trevi.jpg", "level": 0, "country": "Italy", "title": "A grand fountain", "alt": "A huge baroque fountain built into a palace wall, with a marble sea god, horses and rocks above a turquoise pool.", "clue": "Toss a coin over your shoulder into this baroque fountain and, the story goes, you will return to the city.", "story": "The Trevi Fountain in Rome was finished in 1762. Around three thousand euros in coins are thrown in each day, and they go to charity.", "credit": "Wilfredo Rafael Rodriguez Hernandez / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Fontaine_Trevi_-_Rome.jpg"}, {"id": "g-vatican", "image": "places/g-vatican.jpg", "level": 0, "country": "Vatican City", "title": "A dome above a great square", "alt": "A grand basilica with a columned front and a huge dome under a deep blue sky, with colonnades on either side.", "clue": "A great dome partly designed by Michelangelo, at the heart of the world's smallest country.", "story": "St Peter's Basilica stands in Vatican City, an independent country smaller than half a square kilometre, inside Rome. Its dome, finished in 1590, is one of the tallest in the world.", "credit": "Alvesgaspar / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Basilica_di_San_Pietro_in_Vaticano_September_2015-1a.jpg"}, {"id": "g-versailles", "image": "places/g-versailles.jpg", "level": 0, "country": "France", "title": "A hall of mirrors", "alt": "A long palace gallery lined with tall mirrors, crystal chandeliers and golden statues, with a painted ceiling and sunlight on the floor.", "clue": "A long gallery of 357 mirrors in a king's palace, where a treaty ending a world war was signed.", "story": "The Hall of Mirrors at the Palace of Versailles, near Paris, was finished in 1684. The Treaty of Versailles was signed there in 1919.", "credit": "Myrabella / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Chateau_Versailles_Galerie_des_Glaces.jpg"}, {"id": "g-victoria", "image": "places/g-victoria.jpg", "level": 0, "country": "Zimbabwe", "title": "Smoke that thunders", "alt": "A wide waterfall pouring into a deep gorge, with spray rising and a bright rainbow over the cliffs.", "clue": "Locals call it \"the smoke that thunders\": a curtain of water almost two kilometres wide.", "story": "Victoria Falls lies on the Zambezi river between Zimbabwe and Zambia; this view is from the Zimbabwe side. Its spray can be seen from 50 km away, and on full-moon nights it can even make a moonbow.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Cataratas_Victoria,_Zambia-Zimbabue,_2018-07-27,_DD_30-34_PAN.jpg"}, {"id": "g-victoriamem", "image": "places/g-victoriamem.jpg", "level": 0, "country": "India", "title": "A white marble memorial", "alt": "A white marble palace with a great central dome topped by a dark statue of an angel, behind neat green gardens.", "clue": "A marble memorial to a queen-empress, in the city that was once the capital of the British Raj.", "story": "The Victoria Memorial in Kolkata opened in 1921 and is now a museum. The bronze Angel of Victory on its dome turns with the wind.", "credit": "Subhrajyoti07 / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Victoria_Memorial_situated_in_Kolkata.jpg"}, {"id": "g-watarun", "image": "places/g-watarun.jpg", "level": 0, "country": "Thailand", "title": "Guardians at the temple door", "alt": "A temple hall with tiered orange roofs and a white spire, among sculpted trees and a tall guardian statue.", "clue": "A riverside 'Temple of Dawn' in a kingdom that was never colonised.", "story": "This hall is part of Wat Arun, the Temple of Dawn, on the Chao Phraya river in Bangkok. Its great spire is decorated with pieces of colourful Chinese porcelain.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Templo_Wat_Arun,_Bangkok,_Tailandia,_2013-08-22,_DD_30.jpg"}, {"id": "m-aitbenhaddou", "image": "places/m-aitbenhaddou.jpg", "level": 1, "country": "Morocco", "title": "Camels by a mud-brick village", "alt": "Two pale camels nose to nose in front of the towers and walls of a village built of red earth, among palm trees.", "clue": "A fortified village of red earth on an old caravan route over the Atlas Mountains, seen in many films.", "story": "Aït Benhaddou in Morocco is a ksar, a group of earthen buildings behind high walls. Its walls are repaired with mud after the winter rains.", "credit": "Petar Milošević / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Camels_at_A%C3%AFt_Benhaddou,_Saharan_caravan_route,_Morocco_(%D8%A2%D9%8A%D8%AA_%D8%A8%D9%86_%D8%AD%D8%AF%D9%91%D9%88,_%E2%B4%B0%E2%B5%A2%E2%B5%9C_%E2%B5%83%E2%B4%B0%E2%B4%B7%E2%B4%B7%E2%B5%93).jpg"}, {"id": "m-alleppey", "image": "places/m-alleppey.jpg", "level": 1, "country": "India", "title": "A houseboat on the backwaters", "alt": "A wooden houseboat with a curved roof of woven palm and bamboo, floating on calm water lined with coconut palms.", "clue": "A rice-barge turned houseboat with a roof of woven palm leaves, on a maze of palm-lined lagoons by the Arabian Sea.", "story": "The kettuvallam houseboats of the Kerala backwaters were once used to carry rice and spices. Today visitors stay on them and drift through the canals.", "credit": "Ingo Mehling / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Nedumudy_-_Houseboat.jpg"}, {"id": "m-angel", "image": "places/m-angel.jpg", "level": 1, "country": "Venezuela", "title": "A waterfall from the clouds", "alt": "A ribbon of water dropping from a high cliff into mist, with cloud drifting across the rock face.", "clue": "The world's tallest uninterrupted waterfall, dropping almost a kilometre from a flat-topped mountain.", "story": "Angel Falls in Venezuela plunges 979 metres from the top of Auyán-tepui. It is named after Jimmie Angel, a pilot who flew over it in 1933.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Salto_del_Angel-Canaima-Venezuela18.JPG"}, {"id": "m-antelope", "image": "places/m-antelope.jpg", "level": 1, "country": "United States", "title": "A canyon of waves", "alt": "Looking up through a narrow slot canyon of smooth, flowing red sandstone walls to a strip of blue sky.", "clue": "A slot canyon of smooth wave-shaped red sandstone, carved by flash floods on Navajo land in the south-west.", "story": "Antelope Canyon in Arizona can only be visited with a Navajo guide. Sunbeams shine down into it at midday in summer.", "credit": "King of Hearts / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Lower_Antelope_Canyon_November_2018_006.jpg"}, {"id": "m-antigua", "image": "places/m-antigua.jpg", "level": 1, "country": "Guatemala", "title": "An arch below a volcano", "alt": "A yellow arch with a clock tower over a cobbled street of colourful houses, with a large volcano behind.", "clue": "A yellow arch across a cobbled street in an old colonial capital ringed by three volcanoes in Central America.", "story": "The Santa Catalina Arch in Antigua Guatemala was built in the 1600s so nuns could cross the street unseen. The Volcán de Agua rises behind it.", "credit": "Chad Davis / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Santa_Catalina_Arch_-_Antigua_Guatemala_Feb_2020.jpg"}, {"id": "m-apostles", "image": "places/m-apostles.jpg", "level": 1, "country": "Australia", "title": "Stone stacks in the surf", "alt": "Golden limestone stacks standing in a foaming sea beside tall coastal cliffs under a cloudy sky.", "clue": "Limestone stacks standing in the surf beside one of the world's great coastal drives.", "story": "The Twelve Apostles stand off the Great Ocean Road in Victoria, Australia. There were never twelve; waves wear them down, and only a few still stand.", "credit": "Dietmar Rabich / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Princetown_(AU),_Port_Campbell_National_Park,_Twelve_Apostles_--_2019_--_0969.jpg"}, {"id": "m-atacama", "image": "places/m-atacama.jpg", "level": 1, "country": "Chile", "title": "The Valley of the Moon", "alt": "A dry valley of pale sand, salt crusts and eroded rock ridges, with a great sandstone wall like an amphitheatre behind.", "clue": "A 'Valley of the Moon' of salt and sand in the driest non-polar desert on Earth, high on a long Pacific coast.", "story": "Valle de la Luna lies near San Pedro de Atacama in Chile. Some weather stations in the Atacama Desert have never recorded rain.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Anfiteatro,_Valle_de_la_Luna,_San_Pedro_de_Atacama,_Chile,_2016-02-01,_DD_149.JPG"}, {"id": "m-bagan", "image": "places/m-bagan.jpg", "level": 1, "country": "Myanmar", "title": "A plain of temples", "alt": "Old brick temples with pointed spires rising from green bushes under a grey sky.", "clue": "More than 2,000 brick temples and pagodas scattered across a river plain.", "story": "Bagan in Myanmar was a royal capital from the 800s to the 1200s, when over 10,000 temples were built there.", "credit": "Jakub Hałun / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:20160801_Bagan_temples_6701.jpg"}, {"id": "m-banaue", "image": "places/m-banaue.jpg", "level": 1, "country": "Philippines", "title": "A village in the terraces", "alt": "A small village of houses with red and silver roofs among curving, flooded rice terraces climbing a mountainside.", "clue": "Rice terraces carved into mountains by the Ifugao people about 2,000 years ago, on a northern island of a country of 7,000 islands.", "story": "The Batad rice terraces near Banaue in the Philippines form a giant amphitheatre. They are still farmed by hand.", "credit": "CEphoto, Uwe Aranas / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Banaue_Philippines_Batad-Rice-Terraces-02.jpg"}, {"id": "m-bandiagara", "image": "places/m-bandiagara.jpg", "level": 1, "country": "Mali", "title": "Granaries under a cliff", "alt": "Tall round and square mud-brick granaries and houses packed against the foot of a high sandstone cliff.", "clue": "Mud-brick villages and granaries built along a 150-kilometre cliff by the Dogon people, south of the great bend of the Niger.", "story": "The Bandiagara Escarpment in Mali is home to the Dogon, who have lived there since around the 14th century. Older cliff dwellings were built by the Tellem people before them.", "credit": "Kirua / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Villagedogon.jpg"}, {"id": "m-baobab", "image": "places/m-baobab.jpg", "level": 1, "country": "Madagascar", "title": "An avenue of giants", "alt": "A dirt road lined with enormous bottle-shaped trees, with people walking at dusk.", "clue": "Huge bottle-shaped trees on a big island off the south-east coast of a continent.", "story": "The Avenue of the Baobabs in Madagascar has trees up to 800 years old. Most of the world's baobab species grow only on this island.", "credit": "Gavinevans / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Walking_the_Avenue_of_the_Baobabs.jpg"}, {"id": "m-bled", "image": "places/m-bled.jpg", "level": 1, "country": "Slovenia", "title": "An island church on a lake", "alt": "A small island with a white church tower on a blue-green lake, with forested hills, a clifftop castle and cloudy mountains behind.", "clue": "A tiny island church with a wishing bell, reached by wooden rowing boats across an Alpine lake.", "story": "Lake Bled in Slovenia has the country's only natural island. Visitors climb 99 steps to the church and ring its wishing bell; the castle on the cliff is more than a thousand years old.", "credit": "Abrget47j / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:SloveeniaBled.jpg"}, {"id": "m-boudha", "image": "places/m-boudha.jpg", "level": 1, "country": "Nepal", "title": "Eyes on the stupa", "alt": "A white dome topped by a golden tower painted with watchful eyes, strung with colourful prayer flags.", "clue": "A great white dome with painted eyes, in a valley below the highest mountains on Earth.", "story": "Boudhanath in Kathmandu, Nepal, is one of the largest stupas in the world. The eyes on its tower are the all-seeing eyes of the Buddha.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Boudhanath_stupa,_Kathmandu_01.jpg"}, {"id": "m-brussels", "image": "places/m-brussels.jpg", "level": 1, "country": "Belgium", "title": "Golden guildhouses at night", "alt": "Ornate stone guildhouses with gilded statues and gables, lit up at night around a cobbled square.", "clue": "Gilded guildhouses around a square that is covered in a carpet of flowers every other summer.", "story": "The Grand-Place in Brussels, Belgium, is lined with guildhouses rebuilt after 1695. Every two years a Flower Carpet of about half a million begonias fills the square.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Edificios_en_la_Grand-Place,_Bruselas,_B%C3%A9lgica,_2021-12-15,_DD_184-186_HDR.jpg"}, {"id": "m-budapest", "image": "places/m-budapest.jpg", "level": 1, "country": "Hungary", "title": "A bridge of lights", "alt": "A chain bridge lit up at night over a wide river, with a domed parliament glowing beyond.", "clue": "Three old towns on either side of a great river joined to become one capital in 1873.", "story": "The Széchenyi Chain Bridge in Budapest opened in 1849 as the first permanent bridge across the Danube there.", "credit": "Wilfredor / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Sz%C3%A9chenyi_Chain_Bridge_in_Budapest_at_night.jpg"}, {"id": "m-bungle", "image": "places/m-bungle.jpg", "level": 1, "country": "Australia", "title": "Beehive domes", "alt": "A rounded rock dome striped in orange and grey bands like a beehive, with grass and pale trees at its base.", "clue": "Striped orange-and-black sandstone domes like giant beehives, in the remote north-west outback.", "story": "The Bungle Bungle Range in Purnululu National Park, Australia, was little known outside the area until the 1980s. The dark stripes are bacteria living in the rock.", "credit": "W. Bulach / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:A_Kimberleys_-_Australien_(Bungle_Bungle_N.P.).jpg"}, {"id": "m-cameron", "image": "places/m-cameron.jpg", "level": 1, "country": "Malaysia", "title": "Hills of tea", "alt": "Rounded hills covered in neat rows of bright green tea bushes, with forest above and grey clouds.", "clue": "Tea gardens in cool highlands that colonial planters opened in the 1920s, a few hours from a tropical capital of twin towers.", "story": "The Cameron Highlands in Malaysia are about 1,500 metres up, cool enough for tea. Its plantations also grow strawberries and vegetables.", "credit": "Jakub Hałun / Wikimedia Commons", "licence": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Cameron_Bharat_Tea_Plantation,_Cameron_Highlands,_Malaysia,_20250829_1514_4106.jpg"}, {"id": "m-capecoast", "image": "places/m-capecoast.jpg", "level": 1, "country": "Ghana", "title": "A white castle by the sea", "alt": "A large whitewashed castle courtyard with a double staircase, old cannons and cannonballs, under a hazy sky.", "clue": "A whitewashed castle on the Gulf of Guinea, a sad reminder of the Atlantic slave trade on the old Gold Coast.", "story": "Cape Coast Castle in Ghana was built by European traders in the 1600s. Today it is a museum that remembers the people held there.", "credit": "Matti Blume / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Castle,_Cape_Coast_(P1100223).jpg"}, {"id": "m-cappadocia", "image": "places/m-cappadocia.jpg", "level": 1, "country": "Turkey", "title": "Balloons over fairy chimneys", "alt": "A striped hot-air balloon floating over a valley of cone-shaped rock towers.", "clue": "Soft volcanic rock carved by wind into 'fairy chimneys', with homes and churches cut inside them.", "story": "Cappadocia in central Turkey has whole underground cities carved into the rock. Hundreds of balloons rise over it at dawn.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Hot_air_balloon_in_Cappadocia_02.jpg"}, {"id": "m-cartagena", "image": "places/m-cartagena.jpg", "level": 1, "country": "Colombia", "title": "Balconies on the square", "alt": "Colourful colonial buildings with wooden balconies and street lamps around a square.", "clue": "A walled Caribbean port city with flower-filled wooden balconies.", "story": "Cartagena's walled old town in Colombia was built to protect Spanish treasure ships from pirates.", "credit": "Dr. Thomas Liptak / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Colombia,_Cartagena,_Plaza_de_la_Aduana.jpg"}, {"id": "m-charyn", "image": "places/m-charyn.jpg", "level": 1, "country": "Kazakhstan", "title": "A canyon of red towers", "alt": "A deep canyon of red and orange sandstone cliffs and towers winding away into a wide, dry landscape.", "clue": "A red sandstone canyon on the steppe, sometimes called the little brother of a famous one in America, near the old capital Almaty.", "story": "Charyn Canyon in Kazakhstan is about 80 kilometres long. Its 'Valley of Castles' has rock towers shaped by wind and water.", "credit": "Bgag / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Charyn_Canyon,_Kazakhstan_04.jpg"}, {"id": "m-chefchaouen", "image": "places/m-chefchaouen.jpg", "level": 1, "country": "Morocco", "title": "The blue lanes", "alt": "A narrow lane and steps where every wall and door is painted shades of blue.", "clue": "A mountain town in North Africa where almost everything is painted blue.", "story": "Chefchaouen in the Rif mountains of Morocco has painted its old town blue for generations; theories range from keeping it cool to keeping mosquitoes away.", "credit": "Fbrandao.1963 / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:2018_01_(Blue)_-_Chaouen.jpg"}, {"id": "m-chocolate", "image": "places/m-chocolate.jpg", "level": 1, "country": "Philippines", "title": "Hills like sweets", "alt": "Hundreds of round grassy hills scattered across a green landscape.", "clue": "More than a thousand dome-shaped hills that turn brown in the dry season, on an island in a 7,000-island nation.", "story": "The Chocolate Hills on Bohol are named for their brown colour in the dry season, when they look like chocolate drops.", "credit": "rogel tura / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:The_Chocolate_Hills_in_Bohol.jpg"}, {"id": "m-cinqueterre", "image": "places/m-cinqueterre.jpg", "level": 1, "country": "Italy", "title": "Terraces above the sea", "alt": "Steep hillside vineyards on stone terraces dropping to a deep blue sea, with coastal villages beyond.", "clue": "Five fishing villages linked by footpaths along a steep coast of vineyards above the Ligurian Sea.", "story": "The Cinque Terre villages lie on the Ligurian coast. Their dry-stone terraces stretch for thousands of kilometres and were built by hand over centuries.", "credit": "Tagooty/Template:Credits / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Manarola_NW_Cemetery_Corniglia_Monterosso_Cinque_Terre_Sep23_A7C_06872.jpg"}, {"id": "m-cocora", "image": "places/m-cocora.jpg", "level": 1, "country": "Colombia", "title": "The tallest palms", "alt": "Very tall, thin palm trees standing on a bright green hillside, fading into the mist.", "clue": "The world's tallest palm trees, up to 60 metres high, in a misty valley of the coffee-growing Andes.", "story": "The Cocora Valley in Colombia is home to the Quindío wax palm, the national tree. The palms can live for more than a hundred years.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Valle_de_Cocora,_Colombia_04.jpg"}, {"id": "m-colmar", "image": "places/m-colmar.jpg", "level": 1, "country": "France", "title": "Half-timbered houses by a canal", "alt": "Colourful half-timbered houses with flower boxes lining a still canal, reflected in the water.", "clue": "Painted half-timbered houses along a canal nicknamed 'Little Venice', in a wine region on a river border with its eastern neighbour.", "story": "Colmar in Alsace, France, is known for its old houses and canals. The Statue of Liberty's sculptor, Auguste Bartholdi, was born there.", "credit": "Krzysztof Golik / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Little_Venice_in_Colmar_01.jpg"}, {"id": "m-darvaza", "image": "places/m-darvaza.jpg", "level": 1, "country": "Turkmenistan", "title": "A crater on fire", "alt": "A huge crater in a flat desert, with flames burning in many places across its floor and rocky walls.", "clue": "A gas crater in the Karakum Desert that has been burning since it was set alight in 1971.", "story": "The Darvaza gas crater in Turkmenistan is nicknamed the 'Door to Hell'. It is about 70 metres wide and glows at night.", "credit": "Benjamin Goetzinger / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Darvaza_gas_crater,_J%C3%A4hennem_derwezesi,_Door_to_Hell,_Gates_of_Hell,_Derweze,_Turkmenistan.jpg"}, {"id": "m-djenne", "image": "places/m-djenne.jpg", "level": 1, "country": "Mali", "title": "A mud-brick mosque on market day", "alt": "A huge mosque built of earth with spiky towers and wooden beams, above a busy market of colourful stalls.", "clue": "The largest mud-brick building in the world, re-plastered by the whole town at a festival each year.", "story": "The Great Mosque of Djenné in Mali was rebuilt in its present form in 1907. Each year the townspeople join in the Crépissage, a festival to spread fresh mud over its walls.", "credit": "Dr. Ondřej Havelka (cestovatel) / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:The_Great_Clay_Mosque_in_Djenne,_Mali.jpg"}, {"id": "m-dubrovnik", "image": "places/m-dubrovnik.jpg", "level": 1, "country": "Croatia", "title": "A walled city by the sea", "alt": "A walled old town with orange roofs and a small harbour on a blue sea.", "clue": "A walled 'Pearl of the Adriatic' that starred as a fantasy capital on television.", "story": "Dubrovnik's city walls run almost 2 km around the old town and date mostly from the 1300s to 1500s.", "credit": "kallerna / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Dubrovnik_Old_Town_1.jpg"}, {"id": "m-ella", "image": "places/m-ella.jpg", "level": 1, "country": "Sri Lanka", "title": "A bridge of nine arches", "alt": "A curving stone railway bridge of tall arches crossing a valley thick with jungle.", "clue": "A railway viaduct of nine stone arches in the green hill country of a teardrop-shaped island famous for tea.", "story": "The Nine Arch Bridge near Ella in Sri Lanka was finished in 1921 and is built of stone, brick and cement without steel. Blue trains cross it several times a day.", "credit": "Ishan shanuka / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Nine_arch_bridge,_Ella,_Sri_lanka.jpg"}, {"id": "m-ellora", "image": "places/m-ellora.jpg", "level": 1, "country": "India", "title": "A temple cut from a cliff", "alt": "A temple carved down out of a single grey rock cliff, with stone elephants and deep galleries cut into the walls around it.", "clue": "A whole temple carved downwards out of one rock cliff, among caves of three faiths on a western plateau.", "story": "The Kailasa Temple at Ellora in Maharashtra was cut from the rock in the 8th century. Workers removed about 200,000 tonnes of stone to make it.", "credit": "Rohit Sharma / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Courtyard_and_Mahabharata_Reliefs_at_the_Kailasa_Temple,_Ellora_01.jpg"}, {"id": "m-fitzroy", "image": "places/m-fitzroy.jpg", "level": 1, "country": "Argentina", "title": "Granite spires over a lake", "alt": "Jagged granite spires capped with snow rising above green hills and a dark lake, in golden evening light.", "clue": "Jagged granite peaks on the Patagonian ice field, in a trekking village that calls itself the national capital of trekking.", "story": "Monte Fitz Roy in Argentina is 3,405 metres tall. The Tehuelche people called it Chaltén, the 'smoking mountain', because clouds often gather at its top.", "credit": "Gagea / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Fitz_Roy_group_-_Laguna_Capri_-_01.JPG"}, {"id": "m-galapagos", "image": "places/m-galapagos.jpg", "level": 1, "country": "Ecuador", "title": "A giant tortoise in the grass", "alt": "A huge tortoise with a domed shell walking through bright green grass under small trees.", "clue": "Island tortoises like this one helped inspire a famous theory about how species change.", "story": "Giant tortoises live on the Galápagos Islands of Ecuador and can weigh over 250 kg and live more than 100 years. Charles Darwin noticed the shells differed from island to island.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Santa_Cruz_giant_tortoise_03.jpg"}, {"id": "m-gardensbay", "image": "places/m-gardensbay.jpg", "level": 1, "country": "Singapore", "title": "A steel supertree", "alt": "Looking up at a giant steel tree-like tower with a crown of branching metal arms against a cloudy sky.", "clue": "Giant steel 'supertrees' covered in plants, in a garden on reclaimed land in a small island city-state near the equator.", "story": "The Supertree Grove at Gardens by the Bay in Singapore opened in 2012. The trees are up to 50 metres tall and light up in a show every evening.", "credit": "Mike Peel/Attribution / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:At_Singapore_2023_125_-_At_Supertree_Grove.jpg"}, {"id": "m-geiranger", "image": "places/m-geiranger.jpg", "level": 1, "country": "Norway", "title": "A winding fjord", "alt": "A deep blue fjord curving between steep green mountains.", "clue": "A long, narrow fjord on a rugged northern coast, with waterfalls known as the Seven Sisters.", "story": "The Geirangerfjord in Norway is a UNESCO World Heritage Site. Abandoned farms still cling to its cliffs.", "credit": "Ximonic (Simo Räsänen) / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Geirangerfjord_from_%C3%98rnesvingen,_2013_June.jpg"}, {"id": "m-ghardaia", "image": "places/m-ghardaia.jpg", "level": 1, "country": "Algeria", "title": "A desert town on a hill", "alt": "A dense town of pale, flat-roofed houses climbing a low hill in a dry red-brown valley, with a minaret at the top.", "clue": "Five fortified hill towns in a valley of the Sahara, whose simple cube houses inspired modern architects.", "story": "Ghardaïa in Algeria is one of the towns of the M'zab valley, founded about a thousand years ago. The architect Le Corbusier admired its plain houses.", "credit": "*Le_M'Zab.jpg: Yves Jalabert / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Le_M%27Zab-2.jpg"}, {"id": "m-giants", "image": "places/m-giants.jpg", "level": 1, "country": "United Kingdom", "title": "Stepping stones of a giant", "alt": "Thousands of six-sided stone columns stepping down into a wild blue sea, with walkers on the cliffs.", "clue": "About 40,000 six-sided basalt columns by the sea, said in legend to be stepping stones built by a giant to cross to Scotland.", "story": "The Giant's Causeway in Northern Ireland formed when lava cooled and cracked about 50 million years ago. Most of the columns are hexagons.", "credit": "Chmee2 / Wikimedia Commons", "licence": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Giant%27s_Causeway_(14).JPG"}, {"id": "m-gobi", "image": "places/m-gobi.jpg", "level": 1, "country": "Mongolia", "title": "Singing dunes", "alt": "Long pale sand dunes stretching to the horizon beside a strip of green grass, under a blue sky with small clouds.", "clue": "Huge 'singing' sand dunes in a cold desert in the south of a land of nomads, horses and round felt tents.", "story": "Khongoryn Els in Mongolia's Gobi Desert stretches for about 180 kilometres. The dunes hum when the wind moves the sand.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Khongoryn_Els_15.jpg"}, {"id": "m-guilin", "image": "places/m-guilin.jpg", "level": 1, "country": "China", "title": "A river among karst peaks", "alt": "A winding river through flat green fields, among dozens of steep, rounded limestone peaks fading into the haze.", "clue": "Steep limestone peaks along a winding river, a landscape painted on the country's 20-yuan banknote.", "story": "The Li River runs between Guilin and Yangshuo in southern China. Its karst hills are hundreds of millions of years old.", "credit": "Chensiyuan / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:1_li_jiang_guilin_yangshuo_2011.jpg"}, {"id": "m-hallstatt", "image": "places/m-hallstatt.jpg", "level": 1, "country": "Austria", "title": "A village on the lake", "alt": "Painted wooden houses and a white church spire along a still lake, below steep wooded mountains.", "clue": "An Alpine lakeside village that has mined salt for 7,000 years, so pretty it has been copied in China.", "story": "Hallstatt in Austria gave its name to an Iron Age culture. A full-size copy of the village was built in Guangdong, China, in 2012.", "credit": "C.Stadler/Bwag / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Hallstatt_-_Zentrum_.JPG"}, {"id": "m-halong", "image": "places/m-halong.jpg", "level": 1, "country": "Vietnam", "title": "Islands in the bay", "alt": "Tall limestone islands rising from calm green water, with white cruise boats.", "clue": "Thousands of limestone islands rise from a bay whose name means 'where the dragon descends'.", "story": "Ha Long Bay in Vietnam has around 1,600 limestone islands and islets. Many have caves you can sail into.", "credit": "Jakub Hałun / Wikimedia Commons", "licence": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "source": "https://commons.wikimedia.org/wiki/File:View_of_sea_from_Titov_Island,_Ha_Long_Bay,_Vietnam,_20240128_1337_3732.jpg"}, {"id": "m-hampi", "image": "places/m-hampi.jpg", "level": 1, "country": "India", "title": "A temple tower among boulders", "alt": "A tall tiered temple tower of carved stone above a dusty path, with a landscape of huge rounded boulders behind and two women walking.", "clue": "A towering temple gateway in the ruined capital of a great southern empire, set among hills of giant balanced boulders.", "story": "Hampi in Karnataka was the capital of the Vijayanagara Empire in the 1500s. The Virupaksha Temple has been in worship for over a thousand years.", "credit": "iMahesh / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:People_walking_uphill_from_Virupaksha_temple.jpg"}, {"id": "m-havana", "image": "places/m-havana.jpg", "level": 1, "country": "Cuba", "title": "Classic cars on the boulevard", "alt": "Brightly coloured 1950s cars parked in front of a white domed building and an ornate palace.", "clue": "An island capital where colourful American cars from the 1950s still drive the streets.", "story": "Havana's El Capitolio was finished in 1929. The classic cars are kept running with home-made parts.", "credit": "Fraganda / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:National-Capitol-and-classic-cars-in-Havana-Cuba-225-031-061A.jpg"}, {"id": "m-hawamahal", "image": "places/m-hawamahal.jpg", "level": 1, "country": "India", "title": "A palace of windows", "alt": "A pink sandstone palace front with hundreds of small latticed windows above a busy street.", "clue": "A 'Palace of Winds' in a pink-painted city, built so royal women could watch street life unseen.", "story": "Hawa Mahal in Jaipur was built in 1799. Its 953 small windows let breezes through to keep it cool.", "credit": "Jakub Hałun / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:20191218_Pa%C5%82ac_Wiatr%C3%B3w_w_Jaipurze_1129_9124.jpg"}, {"id": "m-hunza", "image": "places/m-hunza.jpg", "level": 1, "country": "Pakistan", "title": "A valley of poplars", "alt": "A green valley of poplar trees and terraced fields beside a winding river, surrounded by bare brown mountains and snowy peaks.", "clue": "A green valley of apricot orchards and poplars on the old Silk Road, ringed by some of the highest peaks of the Karakoram.", "story": "The Hunza Valley in Pakistan lies along the Karakoram Highway. Its villages are famous for apricots and for views of Rakaposhi, over 7,700 metres tall.", "credit": "Alllexxxis / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Hunza_Valley,_view_from_Eagle%27s_Nest.jpg"}, {"id": "m-iceland", "image": "places/m-iceland.jpg", "level": 1, "country": "Iceland", "title": "A waterfall in the mist", "alt": "A wide waterfall pouring off a green cliff into mist.", "clue": "A land of glaciers and volcanoes where waterfalls drop off the old sea cliffs.", "story": "Skógafoss in Iceland falls 60 metres. On sunny days its spray almost always makes a rainbow.", "credit": "Martin Falbisoner / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Sk%C3%B3gafoss_July_2014.JPG"}, {"id": "m-inari", "image": "places/m-inari.jpg", "level": 1, "country": "Japan", "title": "A tunnel of gates", "alt": "A path through a tunnel of bright orange wooden gates painted with black writing.", "clue": "Thousands of orange gates, each donated by a person or business, lead up a sacred mountain.", "story": "Fushimi Inari Taisha in Kyoto has around 10,000 torii gates. The writing on each one names who gave it.", "credit": "Basile Morin / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Torii_path_with_lantern_at_Fushimi_Inari_Taisha_Shrine,_Kyoto,_Japan.jpg"}, {"id": "m-isfahan", "image": "places/m-isfahan.jpg", "level": 1, "country": "Iran", "title": "A great square", "alt": "A vast square with gardens and fountains, framed by turquoise domes and arcades, seen through an arch.", "clue": "A royal square so grand that a proverb called the city 'half the world'.", "story": "Naqsh-e Jahan Square in Isfahan was built in the early 1600s by Shah Abbas I. Polo was once played on it.", "credit": ":en:User:Arad / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Naghshe_Jahan_Square_Isfahan_modified.jpg"}, {"id": "m-iskanderkul", "image": "places/m-iskanderkul.jpg", "level": 1, "country": "Tajikistan", "title": "A turquoise mountain lake", "alt": "A bright turquoise lake winding between steep, bare mountain slopes in shades of red, grey and green.", "clue": "A turquoise lake in the Fann Mountains, in a small mountain country north of Afghanistan.", "story": "The Fann Mountains in Tajikistan are dotted with turquoise lakes. Legend says nearby Iskanderkul is named after Alexander the Great.", "credit": "Oleg Brovko from Halle (Saale), Germany / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Fann_Mountains_-_lake.jpg"}, {"id": "m-jaisalmer", "image": "places/m-jaisalmer.jpg", "level": 1, "country": "India", "title": "A golden fort", "alt": "Massive round bastions of golden sandstone rising above a stone wall, under a blue sky with white clouds.", "clue": "A 'Golden Fort' of yellow sandstone in the Thar Desert, where thousands of people still live inside the walls.", "story": "Jaisalmer Fort in Rajasthan was built in 1156. It is one of the few living forts in the world, with homes, shops and temples inside.", "credit": "Clément Bardot / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Jaisalmer_Fort,_India.jpg"}, {"id": "m-jiuzhaigou", "image": "places/m-jiuzhaigou.jpg", "level": 1, "country": "China", "title": "A turquoise lake", "alt": "A perfectly still turquoise lake reflecting steep forested mountainsides and a rocky peak.", "clue": "Lakes of startling turquoise in a mountain valley of nine Tibetan villages, near the home of the giant panda.", "story": "The lakes of Jiuzhaigou in Sichuan get their colour from minerals and very clear water. Fallen trees can be seen lying on the lake beds.", "credit": "CEphoto, Uwe Aranas / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Jiuzhaigou_Sichuan_China_Panda-Lake-02.jpg"}, {"id": "m-khajuraho", "image": "places/m-khajuraho.jpg", "level": 1, "country": "India", "title": "A carved stone temple", "alt": "A sandstone temple with a tall curved spire and pillared porches, every surface covered in fine carvings, on a wide open lawn.", "clue": "Sandstone temples covered in thousands of carved figures, built by the Chandela kings a thousand years ago in the heart of the country.", "story": "The temples of Khajuraho in Madhya Pradesh were built between 950 and 1050. Of about 85 temples, around 25 still stand.", "credit": "Marcin Białek / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Khajuraho_Dulhadeo_2010.jpg"}, {"id": "m-khiva", "image": "places/m-khiva.jpg", "level": 1, "country": "Uzbekistan", "title": "A forest of wooden pillars", "alt": "A prayer hall filled with rows of carved wooden columns under a flat timber ceiling, with light falling through an opening.", "clue": "A mosque hall of over 200 carved wooden pillars, inside the walled inner town of an old Silk Road oasis.", "story": "The Juma Mosque in Khiva, Uzbekistan, has 213 wooden columns; a few are about a thousand years old. Khiva's inner town, Itchan Kala, is ringed by mud-brick walls.", "credit": "Bgag / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Juma_Mosque_(Khiva)_01.jpg"}, {"id": "m-krumlov", "image": "places/m-krumlov.jpg", "level": 1, "country": "Czech Republic", "title": "A castle tower above a river", "alt": "A painted castle tower and red roofs above a wide shallow river with a wooden bridge and colourful houses.", "clue": "A painted castle tower above a bend of the Vltava, in a small medieval town in the south of a country in the heart of Europe.", "story": "Český Krumlov in the Czech Republic has a castle that is the second largest in the country. Its old town has hardly changed since the 1700s.", "credit": "Jakub Hałun / Wikimedia Commons", "licence": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "source": "https://commons.wikimedia.org/wiki/File:%C4%8Cesk%C3%BD_Krumlov_Castle,_Czechia,_20250504_1248_8849.jpg"}, {"id": "m-kyoto", "image": "places/m-kyoto.jpg", "level": 1, "country": "Japan", "title": "A lane to a pagoda", "alt": "A quiet stone lane between old wooden townhouses with paper lanterns, leading up to a five-storey wooden pagoda.", "clue": "A sloping lane of wooden teahouses below a five-storey pagoda, in an old imperial capital of temples and geishas.", "story": "The Yasaka Pagoda in Kyoto's Higashiyama district was rebuilt in 1440. Its lanes are among the best-kept old streets in Japan.", "credit": "Basile Morin / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Yasaka-dori_early_morning_with_street_lanterns_and_the_Tower_of_Yasaka_(Hokan-ji_Temple),_Kyoto,_Japan.jpg"}, {"id": "m-lamu", "image": "places/m-lamu.jpg", "level": 1, "country": "Kenya", "title": "An old Swahili town", "alt": "An old town of whitewashed stone houses and a mosque beside a waterfront full of small boats, seen from the air.", "clue": "An old Swahili stone town on an island in the Indian Ocean, where donkeys still carry goods because there are hardly any cars.", "story": "Lamu Old Town in Kenya is the oldest continuously lived-in Swahili town in East Africa. Dhows still sail from its harbour.", "credit": "Almaddy2022 / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Lamu_Old_Town.jpg"}, {"id": "m-landwasser", "image": "places/m-landwasser.jpg", "level": 1, "country": "Switzerland", "title": "A train on a stone viaduct", "alt": "A red train crossing a curved stone viaduct high above a gorge, heading into a tunnel, with a snowy peak behind.", "clue": "A red mountain train curves off a tall stone viaduct straight into a tunnel in the cliff.", "story": "The Landwasser Viaduct in Switzerland carries the Rhaetian Railway 65 metres above the river. It opened in 1902 and is part of a UNESCO World Heritage railway.", "credit": "Kabelleger / David Gubler / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:RhB_Ge_4-4_II_614_Glacier_Express_on_Landwasser_Viaduct.jpg"}, {"id": "m-lencois", "image": "places/m-lencois.jpg", "level": 1, "country": "Brazil", "title": "Sand and lagoons", "alt": "Seen from above: wide pale sand bars and shallow lagoons with patches of green scrub, stretching towards white dunes.", "clue": "White dunes and rainwater lagoons near the equator on an Atlantic coast, in a country famous for its rainforest.", "story": "The Lençóis Maranhenses in north-eastern Brazil fill with rain each year, making thousands of lagoons between the dunes. Fish appear in them every rainy season.", "credit": "Matheus Hobold Sovernigo / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Parque_Nacional_dos_Len%C3%A7ois_Maranhenses_Matheus_Hobold_Sovernigo_(01).jpg"}, {"id": "m-lisbon", "image": "places/m-lisbon.jpg", "level": 1, "country": "Portugal", "title": "A tram up the hill", "alt": "A red and cream tram climbing a narrow street between tiled buildings with balconies.", "clue": "Old yellow and red trams rattle up the steep hills of a seaside capital on the western edge of Europe.", "story": "Lisbon's trams have climbed its hills since the 1870s. Tram 28 winds through the old Alfama district.", "credit": "Michael Meraner / Wikimedia Commons", "licence": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Lisbon_in_a_day_-_Tram_28_Alfama_(39271341600).jpg"}, {"id": "m-lofoten", "image": "places/m-lofoten.jpg", "level": 1, "country": "Norway", "title": "A fishing village under peaks", "alt": "Red and white wooden houses along the shore of a still bay, beneath jagged rocky mountains.", "clue": "Red fishing cabins under jagged peaks on islands far above the Arctic Circle, where cod is dried on wooden racks.", "story": "Reine is a fishing village in the Lofoten Islands of Norway. In summer the sun never sets there, and in winter the northern lights appear.", "credit": "Jörg Hempel / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Reine_i_Lofoten_LC0148.jpg"}, {"id": "m-london", "image": "places/m-london.jpg", "level": 1, "country": "United Kingdom", "title": "A red bus and a red phone box", "alt": "An old red double-decker bus parked beside a red telephone box on a wet city street lined with stone buildings.", "clue": "A red double-decker and a red telephone box: two icons of one capital's streets.", "story": "This Routemaster bus is in London, United Kingdom. Routemasters served the city from 1956 to 2005 and a few still run on heritage routes; the red K6 phone box was designed by Giles Gilbert Scott in 1935.", "credit": "Jean-Marc Astesana from Voisins le Bretonneux, France / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:First_London_Routemaster_RM1627_(627_DYE)_heritage_route_9_Trafalgar_Square_23_April_2006.jpg"}, {"id": "m-luangprabang", "image": "places/m-luangprabang.jpg", "level": 1, "country": "Laos", "title": "A temple with sweeping roofs", "alt": "A temple with low, layered roofs sweeping almost to the ground, gold decoration on dark wood, and white steps.", "clue": "A temple with layered roofs sweeping to the ground, in a royal town where the Mekong meets another river, and monks collect alms at dawn.", "story": "Wat Xieng Thong in Luang Prabang, Laos, was built in 1560. The whole old town is a World Heritage Site.", "credit": "Basile Morin / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Temple_Wat_Xieng_Thong_-_Luang_Prabang_-_Laos.jpg"}, {"id": "m-maldives", "image": "places/m-maldives.jpg", "level": 1, "country": "Maldives", "title": "A jetty to the lagoon", "alt": "A wooden jetty running across white sand into a turquoise lagoon towards villas on stilts, under palm fronds.", "clue": "Villas on stilts over a lagoon in a nation of about 1,200 coral islands, most barely a metre above the sea.", "story": "This is Thudufushi island in the Maldives. The country is the flattest in the world: its highest natural point is only about 2.4 metres above sea level.", "credit": "Martin Falbisoner / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Diamonds_Thudufushi_Beach_and_Water_Villas,_May_2017_-09.jpg"}, {"id": "m-matterhorn", "image": "places/m-matterhorn.jpg", "level": 1, "country": "Switzerland", "title": "A pyramid of rock", "alt": "A sharp, snow-streaked pyramid-shaped peak above autumn larch forests and a hiking path.", "clue": "A famous pyramid peak on the border between two Alpine countries; a chocolate bar borrowed its shape.", "story": "The Matterhorn above Zermatt is 4,478 metres high. It was first climbed in 1865.", "credit": "Roy Egloff / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:CH.VS.Zermatt_2021-10-17_Matterhorn_8726.jpg"}, {"id": "m-moher", "image": "places/m-moher.jpg", "level": 1, "country": "Ireland", "title": "Cliffs above the ocean", "alt": "Green clifftops falling to a dark ocean, with a small stone tower at the edge.", "clue": "Sheer cliffs on a green Atlantic island famous for its music and rain.", "story": "The Cliffs of Moher in County Clare rise up to 214 metres. O'Brien's Tower was built in 1835 as a viewing point.", "credit": "Berthold Werner / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Ireland_Cliffs_of_Moher_BW_2025-09-11_14-27-51.jpg"}, {"id": "m-monument", "image": "places/m-monument.jpg", "level": 1, "country": "United States", "title": "Red rock giants", "alt": "Tall red sandstone buttes rising from a flat red desert under a cloudy sky.", "clue": "Red sandstone towers on Navajo land, seen in countless cowboy films.", "story": "Monument Valley on the Arizona–Utah border is inside the Navajo Nation. Its buttes rise up to 300 metres above the valley floor.", "credit": "Luca Galuzzi (Lucag) / Wikimedia Commons", "licence": "CC BY-SA 2.5", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.5/", "source": "https://commons.wikimedia.org/wiki/File:West_Mitten_Butte_-_Monument_Valley_Luca_Galuzzi_2007.jpg"}, {"id": "m-moraine", "image": "places/m-moraine.jpg", "level": 1, "country": "Canada", "title": "A turquoise lake", "alt": "A bright turquoise lake below a row of jagged snowy peaks and dark pine forest.", "clue": "A glacier-fed lake coloured by fine 'rock flour', in a national park in the northern Rocky Mountains.", "story": "Moraine Lake lies in Banff National Park in Canada. Its colour comes from glacial rock flour that reflects blue-green light.", "credit": "Florian Fuchs / Wikimedia Commons", "licence": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Lake_Moraine-Banff_National_Park.jpg"}, {"id": "m-pelourinho", "image": "places/m-pelourinho.jpg", "level": 1, "country": "Brazil", "title": "A colonial square", "alt": "A sloping cobbled square with colourful colonial buildings, a large sky-blue one in the middle, and people strolling.", "clue": "A sloping square of colourful colonial buildings in the old centre of the first capital of a huge South American country.", "story": "Pelourinho is the historic centre of Salvador, Brazil. The city's African heritage lives on in its music, food and capoeira.", "credit": "Matti Blume / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Largo_do_Pelourinho,_Salvador_20150719-DSC05452.JPG"}, {"id": "m-peyto", "image": "places/m-peyto.jpg", "level": 1, "country": "Canada", "title": "A wolf-shaped lake", "alt": "A milky turquoise lake in a forested valley between grey mountains, under a sky of white clouds.", "clue": "A glacier-fed turquoise lake shaped like a wolf's head, high in the Rocky Mountains along the Icefields Parkway.", "story": "Peyto Lake in Banff National Park, Canada, gets its colour from rock flour carried in by glacier meltwater. It is named after an early mountain guide, Bill Peyto.", "credit": "Tobias Alt, Tobi 87 / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Peyto_Lake-Banff_NP-Canada.jpg"}, {"id": "m-plitvice", "image": "places/m-plitvice.jpg", "level": 1, "country": "Croatia", "title": "Waterfalls into turquoise", "alt": "Dozens of thin waterfalls pouring down a mossy green cliff into a clear turquoise pool.", "clue": "Sixteen terraced lakes joined by waterfalls, in a forest park in the hills near the Adriatic coast.", "story": "The Plitvice Lakes in Croatia are separated by natural dams of travertine that grow a little every year. Wooden boardwalks run right over the water.", "credit": "Tesla Delacroix / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Plitvice_Lakes1.jpg"}, {"id": "m-positano", "image": "places/m-positano.jpg", "level": 1, "country": "Italy", "title": "A village on a cliff", "alt": "Pastel houses stacked steeply up a hillside above the sea, seen from a terrace with pots of lemons.", "clue": "Pastel houses tumbling down a cliff to the sea, on a coast famous for lemons and winding roads south of Naples.", "story": "Positano on the Amalfi Coast of Italy was once a poor fishing village. Today its steep lanes are mostly stairs, and lemons grown nearby are made into limoncello.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Positano_(Italy)_04.jpg"}, {"id": "m-quilotoa", "image": "places/m-quilotoa.jpg", "level": 1, "country": "Ecuador", "title": "A lake in a crater", "alt": "A large green-blue lake filling a deep volcanic crater, ringed by steep slopes under a sky of big white clouds.", "clue": "A water-filled volcanic crater high in the Andes, on a hiking loop through Kichwa villages on the equator's line of volcanoes.", "story": "Quilotoa in Ecuador is a crater lake about three kilometres wide, formed when a volcano collapsed some 800 years ago. Minerals turn the water green and blue.", "credit": "Annom / Wikimedia Commons", "licence": "Public domain", "licenseUrl": "https://en.wikipedia.org/wiki/Public_domain", "source": "https://commons.wikimedia.org/wiki/File:Panorama_quilotoa_crater_lake_ecuador.jpg"}, {"id": "m-rainbow", "image": "places/m-rainbow.jpg", "level": 1, "country": "Peru", "title": "A mountain of stripes", "alt": "A mountain ridge striped in bands of red, purple, cream and green, with hikers resting at the top.", "clue": "A mountain striped like a rainbow by minerals, high in the Andes above 5,000 metres, near the old Inca capital.", "story": "Vinicunca, the Rainbow Mountain in Peru, was covered by ice until recent decades. Its colours come from minerals such as iron oxide.", "credit": "Laila Goubran / Wikimedia Commons", "licence": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Rainbow_Mountain.jpg"}, {"id": "m-reef", "image": "places/m-reef.jpg", "level": 1, "country": "Australia", "title": "A reef from the air", "alt": "Seen from a plane: turquoise shallows, dark patches of coral and a small white sand island in a deep blue sea.", "clue": "The largest coral reef system in the world, so big it can be seen from space, off a north-eastern coast.", "story": "The Great Barrier Reef off Queensland, Australia, stretches for about 2,300 kilometres. It is made of nearly 3,000 separate reefs.", "credit": "Ank Kumar / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Aerial_View_of_Great_Barrier_Reef_(Ank_Kumar)_04.jpg"}, {"id": "m-registan", "image": "places/m-registan.jpg", "level": 1, "country": "Uzbekistan", "title": "Three blue-tiled schools", "alt": "A square framed by three tiled buildings with huge arched gateways and turquoise domes.", "clue": "Three tiled madrasas around a square on the old Silk Road.", "story": "The Registan in Samarkand is ringed by three madrasas built between 1417 and 1660.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Registan_01.jpg"}, {"id": "m-ronda", "image": "places/m-ronda.jpg", "level": 1, "country": "Spain", "title": "A bridge over a gorge", "alt": "A tall stone bridge spanning a deep gorge between sheer cliffs, with white buildings perched on the edge.", "clue": "A town split by a deep gorge and joined by an 18th-century stone bridge, in the hills of the south, birthplace of modern bullfighting.", "story": "The Puente Nuevo in Ronda, Spain, was finished in 1793 and stands about 98 metres above the river. It took over 40 years to build.", "credit": "Moroder/Template:Credits / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:View_of_Puente_Nuevo_bridge_in_Ronda_Spain.jpg"}, {"id": "m-santorini", "image": "places/m-santorini.jpg", "level": 1, "country": "Greece", "title": "Blue domes by the sea", "alt": "White-washed churches with bright blue domes on a cliff above a deep blue sea.", "clue": "White houses and blue domes on the rim of a flooded volcanic crater in the Aegean.", "story": "Oia on Santorini sits on the edge of a caldera formed by a huge eruption about 3,600 years ago.", "credit": "Giles Laurent / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:1000_Three_domes_of_Oia_in_Santorini_Photo_by_Giles_Laurent.jpg"}, {"id": "m-shirakawago", "image": "places/m-shirakawago.jpg", "level": 1, "country": "Japan", "title": "A steep thatched farmhouse", "alt": "A big wooden farmhouse with a very steep, thick thatched roof, with a garden and visitors in front and forested hills behind.", "clue": "Farmhouses with steep thatched roofs like hands joined in prayer, built to shed heavy mountain snow.", "story": "The gassho-zukuri houses of Shirakawa-go in Japan have roofs up to 60 degrees steep. Villagers rethatch them together every few decades.", "credit": "Gilles Desjardins / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Shirakawa-go_01.jpg"}, {"id": "m-shoretemple", "image": "places/m-shoretemple.jpg", "level": 1, "country": "India", "title": "A temple by the sea", "alt": "Two pyramid-shaped stone temple towers, weathered by sea wind, glowing in warm evening light.", "clue": "A granite temple on the beach of the Bay of Bengal, built by the Pallava kings and battered by sea winds for 1,300 years.", "story": "The Shore Temple at Mahabalipuram in Tamil Nadu was built around 700 AD. The 2004 tsunami uncovered more old carvings in the sand nearby.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Shore_Temple_01.jpg"}, {"id": "m-sighisoara", "image": "places/m-sighisoara.jpg", "level": 1, "country": "Romania", "title": "A cobbled old street", "alt": "A quiet cobbled lane between brightly painted houses in orange, green and yellow, with wooden shutters.", "clue": "Painted houses in a hilltop citadel in Transylvania, where a famous 15th-century prince was said to have been born.", "story": "Sighișoara in Romania is one of the last lived-in medieval citadels in Europe. Vlad the Impaler, who inspired Dracula, was born there.", "credit": "Antony Stanley from Gloucester, UK / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:The_Streets_Of_Sighi%C8%99oara_Citadel_(8153602163).jpg"}, {"id": "m-sigiriya", "image": "places/m-sigiriya.jpg", "level": 1, "country": "Sri Lanka", "title": "A rock fortress", "alt": "A huge flat-topped rock rising above green forest under a cloudy sky.", "clue": "A king's palace was built on top of this huge rock in the 5th century, reached through the paws of a stone lion.", "story": "Sigiriya, or Lion Rock, in Sri Lanka rises about 180 metres. Only the giant lion paws remain of the gateway to the top.", "credit": "Madhawa Dunuwila / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Sigiriya_Fortress,_Sri_Lanka.jpg"}, {"id": "m-songkol", "image": "places/m-songkol.jpg", "level": 1, "country": "Kyrgyzstan", "title": "A horse by a high lake", "alt": "A dark horse standing on a wide grassy plain beside a big blue lake, with low mountains on the far shore.", "clue": "A high mountain lake where nomad herders bring their horses and set up felt yurts each summer, in the Tian Shan.", "story": "Song-Köl in Kyrgyzstan lies about 3,000 metres up. Its lakeside pastures are used only in summer; in winter the lake freezes over.", "credit": "ElPrismaDeFer - [https://elprismadefer.com] / Wikimedia Commons", "licence": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Horse_standing_by_Song_Kul_Lake_-_Kyrgyztan.jpg"}, {"id": "m-sossusvlei", "image": "places/m-sossusvlei.jpg", "level": 1, "country": "Namibia", "title": "A dead tree before red dunes", "alt": "A dead, twisted tree on a white clay pan in front of a huge orange sand dune.", "clue": "Some of the tallest sand dunes on Earth, in one of the oldest deserts.", "story": "Deadvlei in the Namib Desert holds trees that died about 900 years ago. The air is so dry that they have never rotted.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Dead_Vlei,_Sossusvlei,_Namibia,_2018-08-06,_DD_086.jpg"}, {"id": "m-stonehenge", "image": "places/m-stonehenge.jpg", "level": 1, "country": "United Kingdom", "title": "A ring of stones", "alt": "A circle of huge standing stones with lintels across the top, on a green plain under clouds.", "clue": "A prehistoric stone circle aligned with the midsummer sunrise.", "story": "Stonehenge on Salisbury Plain in England was built in stages from about 5,000 years ago. Some stones came from Wales, 225 km away.", "credit": "Sumit Surai / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Stonehenge_from_the_north.jpg"}, {"id": "m-taipei", "image": "places/m-taipei.jpg", "level": 1, "country": "Taiwan", "title": "A bamboo-shaped tower", "alt": "A tall green-glass skyscraper made of stacked sections rising above a city, seen from a wooded hill at sunset.", "clue": "A skyscraper shaped like stacked bamboo, with a giant steel ball inside to steady it in typhoons.", "story": "Taipei 101 in Taiwan was the world's tallest building from 2004 to 2010. A 660-tonne steel ball hanging near the top sways to calm the tower in wind and earthquakes.", "credit": "CEphoto, Uwe Aranas / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Taipei_Taiwan_Taipei-101-Tower-01.jpg"}, {"id": "m-thiksey", "image": "places/m-thiksey.jpg", "level": 1, "country": "India", "title": "A monastery on a hill", "alt": "A many-storeyed white monastery with red-topped buildings stacked up a dry, rocky hillside under a deep blue sky.", "clue": "A white monastery stacked up a hillside in a high, dry mountain desert, sometimes called 'Little Tibet'.", "story": "Thiksey Monastery in Ladakh is built in the style of the Potala Palace in Lhasa. It houses a two-storey statue of the Maitreya Buddha.", "credit": "Bernard Gagnon Canon EOS REBEL T4i / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Thiksey_Monastery,_Ladakh_01.jpg"}, {"id": "m-tigersnest", "image": "places/m-tigersnest.jpg", "level": 1, "country": "Bhutan", "title": "A monastery on a cliff", "alt": "White monastery buildings with golden roofs clinging to a sheer rock face above a forested valley.", "clue": "A monastery clinging to a cliff high above a valley, where a guru is said to have flown in on a tigress.", "story": "Paro Taktsang, the Tiger's Nest, in Bhutan sits about 900 metres above the Paro valley. Legend says Guru Rinpoche flew here on the back of a tigress to meditate in a cave.", "credit": "Nina R; edited by UnpetitproleX / Wikimedia Commons", "licence": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Paro_Taktsang,_Bhutan_(edited).jpg"}, {"id": "m-tikal", "image": "places/m-tikal.jpg", "level": 1, "country": "Guatemala", "title": "A temple in the rainforest", "alt": "A tall stepped stone pyramid with a temple on top, surrounded by rainforest trees and a green lawn.", "clue": "A temple-pyramid of an ancient civilisation rising from the rainforest, home to toucans and howler monkeys.", "story": "This is Temple II at Tikal in Guatemala, one of the greatest Maya cities, home to tens of thousands of people some 1,300 years ago. Today spider monkeys and toucans live among the ruins.", "credit": "Adam Jones from Kelowna, BC, Canada / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Temple_II_-_Gran_Plaza_-_Tikal_Archaeological_Site_-_Peten_-_Guatemala_(15871470705).jpg"}, {"id": "m-tongariro", "image": "places/m-tongariro.jpg", "level": 1, "country": "New Zealand", "title": "Emerald lakes", "alt": "Bright green crater lakes below steaming volcanic slopes of dark rock and red earth.", "clue": "Bright green crater lakes on a famous volcanic day hike, in a volcanic park sacred to the Māori people.", "story": "The Emerald Lakes lie on the Tongariro Alpine Crossing in New Zealand. Their colour comes from minerals washed down from the volcano.", "credit": "Du Hugin Skulblaka / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Emerald_Lakes,_NZ.jpg"}, {"id": "m-tosua", "image": "places/m-tosua.jpg", "level": 1, "country": "Samoa", "title": "A swimming hole in the earth", "alt": "A deep round hole in the ground lined with ferns and vines, with a long wooden ladder down to clear green seawater.", "clue": "A giant swimming hole joined to the sea by a lava tube, on an island nation of the South Pacific.", "story": "To Sua Ocean Trench on Upolu, Samoa, is about 30 metres deep. Swimmers climb down a long wooden ladder to reach the water.", "credit": "Gelu Purcelu / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:To_Sua_Ocean_Trench.jpg"}, {"id": "m-tsingy", "image": "places/m-tsingy.jpg", "level": 1, "country": "Madagascar", "title": "A forest of stone needles", "alt": "A landscape of sharp grey limestone pinnacles packed tightly together, with a strip of green forest beyond.", "clue": "A 'forest' of razor-sharp limestone needles on a large island off south-east Africa, home of lemurs.", "story": "Tsingy de Bemaraha in Madagascar gets its name from a Malagasy word meaning 'where one cannot walk barefoot'. Rope bridges cross between the pinnacles.", "credit": "Unknown photographer / Wikimedia Commons", "licence": "Public domain", "licenseUrl": "https://en.wikipedia.org/wiki/Public_domain", "source": "https://commons.wikimedia.org/wiki/File:Tsingy_de_Bemaraha_Strict_Nature_Reserve.jpg"}, {"id": "m-tulum", "image": "places/m-tulum.jpg", "level": 1, "country": "Mexico", "title": "Ruins above a Caribbean beach", "alt": "A small stone temple on a rocky headland above a white beach and bright turquoise sea, framed by palm trees.", "clue": "A walled Maya city on a cliff above the Caribbean Sea, one of the last the Maya built and lived in.", "story": "Tulum on the Yucatán Peninsula of Mexico was a busy Maya port around 1200 to 1500. The small Temple of the God of the Winds stands right above the sea.", "credit": "Martin Falbisoner / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Tulum_-_God_of_the_Winds_Temple_03.JPG"}, {"id": "m-udaipur", "image": "places/m-udaipur.jpg", "level": 1, "country": "India", "title": "Palaces on a lake", "alt": "White and cream palaces and houses along the shore of a calm lake, with a large hilltop palace behind.", "clue": "A 'City of Lakes' with white palaces on the water, founded by a Rajput king in the hills of the north-west.", "story": "Udaipur in Rajasthan sits on Lake Pichola. Its City Palace was added to by many rulers over about 400 years.", "credit": "Jakub Hałun / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:20191207_Lake_Pichola,_City_Palace,_Udaipur,_1516_7254.jpg"}, {"id": "m-uluru", "image": "places/m-uluru.jpg", "level": 1, "country": "Australia", "title": "A red rock at sunset", "alt": "A huge, glowing red sandstone rock rising from golden grassland under dark storm clouds.", "clue": "A single giant sandstone rock in the middle of a vast red desert, sacred to its Aboriginal custodians.", "story": "Uluṟu rises 348 metres above the plains of central Australia. It is sacred to the Aṉangu people, and climbing it has been banned since 2019.", "credit": "Weyf / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Ulu%E1%B9%9Fu_(Ayers_Rock),_Sunset.jpg"}, {"id": "m-uyuni", "image": "places/m-uyuni.jpg", "level": 1, "country": "Bolivia", "title": "Walking on the sky", "alt": "People standing on a vast, mirror-like flat of water reflecting the sunset sky.", "clue": "The world's largest salt flat, high in the Andes, becomes a giant mirror after rain.", "story": "Salar de Uyuni in Bolivia covers over 10,000 square kilometres. It is so flat that satellites use it to calibrate their instruments.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Salar_de_Uyuni,_Bolivia,_2016-02-04,_DD_16-18_HDR.JPG"}, {"id": "m-varanasi", "image": "places/m-varanasi.jpg", "level": 1, "country": "India", "title": "Steps down to a holy river", "alt": "Old sandstone palaces and long stone steps leading down to a wide river, with wooden rowing boats moored along the bank.", "clue": "Stone steps down to a sacred river in one of the oldest living cities on Earth, where evening prayers are sung with fire.", "story": "Varanasi stands on the banks of the Ganges and has more than 80 ghats, or riverside steps. Pilgrims come to bathe in the river at dawn.", "credit": "Marcin Białek / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Varanasi_Munshi_Ghat3.jpg"}, {"id": "m-venice", "image": "places/m-venice.jpg", "level": 1, "country": "Italy", "title": "A gondola on the canal", "alt": "A gondola gliding along a wide canal lined with old palaces and a domed church.", "clue": "A city of canals instead of roads, built on wooden piles in a lagoon.", "story": "Venice's Grand Canal is lined with palaces built over 600 years. The domed church is Santa Maria della Salute.", "credit": "Moroder/Template:Credits / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Canal_Grande_Chiesa_della_Salute_e_Dogana_dal_ponte_dell_Accademia.jpg"}, {"id": "m-wadirum", "image": "places/m-wadirum.jpg", "level": 1, "country": "Jordan", "title": "Red sand and rock", "alt": "Huge red sandstone rock formations rising from orange desert sand under a clear blue sky.", "clue": "A 'Valley of the Moon' of red sand and towering sandstone, north of the Red Sea, where many films set on Mars are shot.", "story": "Wadi Rum in Jordan is a protected desert of sandstone and granite. Bedouin families have lived there for centuries.", "credit": "Peter Chisholm / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Wadi_rum_desert.jpg"}, {"id": "m-zhangjiajie", "image": "places/m-zhangjiajie.jpg", "level": 1, "country": "China", "title": "Stone pillars in the mist", "alt": "Tall sandstone pillars covered in trees, rising out of the mist.", "clue": "Thousands of sandstone pillars said to have inspired the floating mountains in a blockbuster film.", "story": "The pillars of Zhangjiajie in Hunan province rise up to 200 metres. It became the country's first national forest park in 1982.", "credit": "Dcpeets / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Zhangjiajie_at_dawn_1.jpg"}, {"id": "t-accra", "image": "places/t-accra.jpg", "level": 2, "country": "Ghana", "title": "A busy market", "alt": "A crowded market with stalls of tomatoes, shoes, baskets and colourful goods under umbrellas.", "clue": "A great open-air market in a West African capital on the Gulf of Guinea.", "story": "Makola Market in Accra, Ghana, is one of the biggest markets in West Africa. Most of its traders are women, known as market queens.", "credit": "Nii Adama Armah / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Makola_Market,_Accra,_Ghana.jpg"}, {"id": "t-addis", "image": "places/t-addis.jpg", "level": 2, "country": "Ethiopia", "title": "A blue and white minibus", "alt": "A blue-and-white minibus taxi on a busy street.", "clue": "Blue-and-white minibuses carry most people around this highland capital, the seat of the African Union.", "story": "Addis Ababa in Ethiopia sits about 2,400 metres high. Its blue-and-white minibuses are the city's everyday transport.", "credit": "Radosław Botev, copyright holder: Fundacja Kontroli Społecznej \"Nomos\" / Wikimedia Commons", "licence": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Minibus_taxi_in_Addis_Ababa.jpg"}, {"id": "t-bali", "image": "places/t-bali.jpg", "level": 2, "country": "Indonesia", "title": "Terraces of rice", "alt": "Steep green rice terraces among coconut palms.", "clue": "Rice terraces watered by a 1,000-year-old shared system run by temples, on an island of Hindu temples.", "story": "These terraces are in Bali, Indonesia. Their water is shared through subak, a co-operative system recognised by UNESCO.", "credit": "Vyacheslav Argenberg / Wikimedia Commons", "licence": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Rice_terraces,_Bali.jpg"}, {"id": "t-bangkok", "image": "places/t-bangkok.jpg", "level": 2, "country": "Thailand", "title": "A sign to the pier", "alt": "A green street sign in a looping script with an arrow, above a busy street.", "clue": "Read the sign: rounded letters with little loops, and a pier on a river that carries the city's boats.", "story": "The sign points to Pratu Nam Pier on a canal in Bangkok. Thai script has 44 consonants and no spaces between words.", "credit": "David McKelvey from Brisbane, Australia / Wikimedia Commons", "licence": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Pratu_Nam_Pier,_Bangkok,_Thailand_(6906983490).jpg"}, {"id": "t-bokaap", "image": "places/t-bokaap.jpg", "level": 2, "country": "South Africa", "title": "A pink house", "alt": "A bright pink house front with painted aloe plants, wooden-framed windows and a balcony with magenta balusters.", "clue": "A candy-pink house in a hillside quarter famous for painting its homes in bright colours.", "story": "This house is on Wale Street in the Bo-Kaap, Cape Town, South Africa. The quarter's houses are painted bright colours, and it is famous for its Cape Malay food.", "credit": "Dietmar Rabich / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Cape_Town_(ZA),_Wale_Street_--_2024_--_3536.jpg"}, {"id": "t-cairo", "image": "places/t-cairo.jpg", "level": 2, "country": "Egypt", "title": "Sacks in the spice market", "alt": "Open sacks of spices and dried goods with handwritten price cards in a flowing right-to-left script.", "clue": "Read the price cards: a right-to-left script, in an old market in a big city on a great northern river.", "story": "This is the spice market in Khan el-Khalili, Cairo, a bazaar trading since the 1300s. The labels are written in Arabic.", "credit": "Jon Gudorf Photography / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Cairo_-_Khan_al-Khalili_spice_market_1994.jpg"}, {"id": "t-colombo", "image": "places/t-colombo.jpg", "level": 2, "country": "Sri Lanka", "title": "A west-coast town street", "alt": "A busy street with three-wheeled taxis, motorbikes, shop signs and a domed building.", "clue": "Three-wheeler taxis and shop signs in a rounded script; this island sits just off a big subcontinent's southern tip.", "story": "This is Mannar Road in Puttalam, on Sri Lanka's west coast. The rounded letters on the signs are Sinhala, and tuk-tuks are the everyday taxi.", "credit": "Vincent van Zeijst / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Sri_Lanka,_Puttalam_street_scene_(5).jpg"}, {"id": "t-colonia", "image": "places/t-colonia.jpg", "level": 2, "country": "Uruguay", "title": "A cobbled lane to the river", "alt": "A cobbled lane between old pastel houses and flowering trees, sloping down to a wide brown river.", "clue": "A cobbled colonial lane sloping down to a river so wide it looks like the sea.", "story": "This lane is in Colonia del Sacramento, Uruguay, founded by the Portuguese in 1680. Across the wide Río de la Plata lies Buenos Aires.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Colonia_del_Sacramento3_-_Uruguay.jpg"}, {"id": "t-cusco", "image": "places/t-cusco.jpg", "level": 2, "country": "Peru", "title": "A cathedral on the square", "alt": "A large stone cathedral with twin bell towers above steps where people sit in the sun.", "clue": "A colonial cathedral built on Inca foundations, in a mountain city that was once an empire's capital.", "story": "Cusco Cathedral in Peru was built from 1560 to 1654, partly with stones taken from Inca buildings. Cusco was the capital of the Inca Empire.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Catedral,_Plaza_de_Armas,_Cusco,_Per%C3%BA,_2015-07-31,_DD_73.JPG"}, {"id": "t-dhaka", "image": "places/t-dhaka.jpg", "level": 2, "country": "Bangladesh", "title": "Rickshaws at rest", "alt": "A row of cycle rickshaws with colourful hoods parked on a street under trees.", "clue": "Colourfully decorated cycle rickshaws are everywhere in this river-delta capital, once called the 'rickshaw capital of the world'.", "story": "Dhaka in Bangladesh has hundreds of thousands of cycle rickshaws. Painting their hoods is a folk art of its own.", "credit": "Nasir Khan Saikat @ flickr from Dhaka, Bangladesh / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Rickshaw_Parking_at_Dhaka_(9601873282).jpg"}, {"id": "t-greekvillage", "image": "places/t-greekvillage.jpg", "level": 2, "country": "Greece", "title": "White houses on the hillside", "alt": "A small village of white and stone houses on a terraced hillside with olive trees.", "clue": "White cube houses among olive terraces, on a long mountainous island in the Mediterranean.", "story": "This is the village of Sklavi near Sitia on Crete, Greece. Crete has some of the oldest olive trees in the world.", "credit": "Petro Stelte / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Sklavi-Sitia-Crete.jpg"}, {"id": "t-hanoi", "image": "places/t-hanoi.jpg", "level": 2, "country": "Vietnam", "title": "Motorbikes at the lights", "alt": "A crowd of riders on scooters waiting at a city junction, under a shop sign with lots of accent marks.", "clue": "Read the shop sign: a Latin alphabet with many stacked accent marks, in a capital where motorbikes outnumber cars.", "story": "This is Hanoi, Vietnam. Vietnamese is written in Latin letters with extra marks that show its six tones.", "credit": "Nicolas Lannuzel from Singapore, Singapore / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Hanoi_street_scene-_motorbikes_(22522817795).jpg"}, {"id": "t-ireland", "image": "places/t-ireland.jpg", "level": 2, "country": "Ireland", "title": "A lighthouse on the bay", "alt": "A small white lighthouse on a green clifftop at the mouth of a bay, with patchwork fields behind.", "clue": "A small lighthouse on a peninsula of green fields at the far western edge of Europe, where Gaelic is still spoken.", "story": "Dingle Lighthouse marks the entrance to Dingle Bay in County Kerry, Ireland. The Dingle peninsula is part of the Gaeltacht, where Irish is an everyday language.", "credit": "Superbass / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:2019-07-20-Dingle_Lighthouse-0673.jpg"}, {"id": "t-istanbul", "image": "places/t-istanbul.jpg", "level": 2, "country": "Turkey", "title": "A red tram from above", "alt": "Looking down on a busy pedestrian street with a small red vintage tram passing through.", "clue": "A red nostalgic tram on a busy avenue, in a city that sits on two continents.", "story": "Istiklal Avenue in Istanbul, Turkey, carries a restored red tram. The city spreads across both Europe and Asia.", "credit": "Umit Yurduseven / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:%C4%B0stiklal_Caddesi_%C4%B0stanbul.jpg"}, {"id": "t-japanstreet", "image": "places/t-japanstreet.jpg", "level": 2, "country": "Japan", "title": "A tower in the night city", "alt": "A city of skyscrapers at night with a glowing orange-and-white lattice tower in the middle.", "clue": "A red-and-white lattice tower, inspired by one in Paris, glowing in one of the world's biggest cities.", "story": "Tokyo Tower in Japan opened in 1958. At 333 metres it is a little taller than the Eiffel Tower, which inspired it.", "credit": "David Kernan / Wikimedia Commons", "licence": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Tokyo_Tower,_Minato_City.jpg"}, {"id": "t-jeepney", "image": "places/t-jeepney.jpg", "level": 2, "country": "Philippines", "title": "A long chrome jeep", "alt": "A long chrome jeep-like bus at a junction under tangled power lines and tall buildings.", "clue": "Long chrome jeeps, first rebuilt from army surplus after 1945, are the everyday bus in this island nation's capital.", "story": "Jeepneys in Manila were first made from American army jeeps left after the Second World War. They are known as the 'kings of the road'.", "credit": "Aliceinthealice / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:Jeepney_in_Metro_Manila_2025_01.jpg"}, {"id": "t-jiufen", "image": "places/t-jiufen.jpg", "level": 2, "country": "Taiwan", "title": "Stairs between teahouses", "alt": "A steep stepped lane between small shops with red lanterns and signs in Chinese characters.", "clue": "Steep lanes of teahouses in an old gold-mining town, with shop signs in traditional characters.", "story": "Jiufen in Taiwan grew rich in a gold rush in the 1890s. Its lantern-lit lanes and teahouses look out over the sea, and Taiwan writes Chinese in traditional characters.", "credit": "Another Believer / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Jiufen,_November_28,_2024_-_030.jpg"}, {"id": "t-kolkata", "image": "places/t-kolkata.jpg", "level": 2, "country": "India", "title": "A yellow taxi", "alt": "A round-shouldered yellow taxi on a city street, with another behind and a sun umbrella stall.", "clue": "Rounded yellow taxis from a car first built in 1958, in a big city on a branch of a holy river.", "story": "The yellow Hindustan Ambassador taxis of Kolkata are a symbol of the city. The Ambassador was made in West Bengal for over 50 years.", "credit": "Bernard Gagnon / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Taxi_of_Kolkata.jpg"}, {"id": "t-krakow", "image": "places/t-krakow.jpg", "level": 2, "country": "Poland", "title": "Arcades on the square", "alt": "A long Renaissance hall with arched arcades and café umbrellas on a large market square.", "clue": "A Renaissance cloth hall on one of the largest medieval market squares in Europe.", "story": "The Cloth Hall stands on the Main Market Square in Kraków, Poland. Traders have sold cloth and goods here since the 1300s.", "credit": "Igor123121 / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Krak%C3%B3w_Cloth_Hall,_Caf%C3%A9_Noworolski,_3_Main_Market_square,_Old_Town,_Krak%C3%B3w,_Poland.jpg"}, {"id": "t-lagos", "image": "places/t-lagos.jpg", "level": 2, "country": "Nigeria", "title": "A yellow minibus", "alt": "A yellow minibus with black stripes driving past a footbridge and brick buildings on a busy road.", "clue": "Yellow minibuses with black stripes carry millions of people around a huge West African city.", "story": "Danfo minibuses are the yellow-and-black buses of Lagos, Nigeria. Their conductors call out the destinations as they go, and the city has some of Africa's busiest roads.", "credit": "Kaizenify / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Danfo_buses_on_the_street_of_Lagos_11_38_39_243000.jpeg"}, {"id": "t-laos", "image": "places/t-laos.jpg", "level": 2, "country": "Laos", "title": "Monks at prayer", "alt": "Monks in saffron robes kneeling before a golden seated Buddha in a red and gold temple.", "clue": "Saffron-robed monks in a temple of red and gold, in a quiet royal town where two rivers meet.", "story": "This is Wat Sensoukharam in Luang Prabang, Laos. Every dawn, monks walk the streets to receive offerings of sticky rice.", "credit": "Basile Morin / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Praying_bhikkhus_inside_Wat_Sensoukharam_in_Luang_Prabang_Laos.jpg"}, {"id": "t-lapaz", "image": "places/t-lapaz.jpg", "level": 2, "country": "Bolivia", "title": "A city below the peaks", "alt": "Office blocks in a city filling a deep valley, with a snowy mountain beyond.", "clue": "A city so high in the Andes that its everyday public transport is a network of cable cars.", "story": "La Paz in Bolivia sits about 3,600 metres above sea level. Its Mi Teleférico cable cars are the world's largest urban cable car network.", "credit": "Henryisknow / Wikimedia Commons", "licence": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/", "source": "https://commons.wikimedia.org/wiki/File:La_Paz,_Bolivia_en_la_ma%C3%B1ana.jpg"}, {"id": "t-malta", "image": "places/t-malta.jpg", "level": 2, "country": "Malta", "title": "Painted boats in the harbour", "alt": "Brightly painted wooden fishing boats in blue, yellow and green floating in a harbour in front of a town of pale stone houses.", "clue": "Brightly painted fishing boats, each with a watchful eye on its bow, in a small island nation's harbour.", "story": "These are luzzu boats in Marsaxlokk, a fishing village in Malta. The eye painted on each bow is said to go back to the Phoenicians and to watch over the fishermen.", "credit": "Vlad beu / Wikimedia Commons", "licence": "Public domain", "licenseUrl": "https://en.wikipedia.org/wiki/Public_domain", "source": "https://commons.wikimedia.org/wiki/File:Marsaxlokk_Boat.JPG"}, {"id": "t-marrakech", "image": "places/t-marrakech.jpg", "level": 2, "country": "Morocco", "title": "Lanterns in the souk", "alt": "Dozens of pierced metal lanterns hanging and glowing in a shop.", "clue": "Pierced brass lanterns in the metalworkers' lane of a red-walled old city.", "story": "Souk Haddadine in Marrakech is the blacksmiths' and metalworkers' market. The city's walls and houses are built from red earth.", "credit": "Petar Milošević / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Oriental_hanging_lanterns._Souk_Haddadine,_Marrakech_Medina_(%D8%B3%D9%88%D9%82_%D8%A7%D9%84%D8%AD%D8%AF%D8%A7%D8%AF%D9%8A%D9%86_%D9%85%D8%B1%D8%A7%D9%83%D8%B4).jpg"}, {"id": "t-mongolia", "image": "places/t-mongolia.jpg", "level": 2, "country": "Mongolia", "title": "A felt tent on the steppe", "alt": "A round white felt tent standing alone on wide, dry grassland under a big sky.", "clue": "A land of nomads, where families still live in round felt tents that can be packed up in an hour.", "story": "The ger is the traditional home in Mongolia; this one stands on the steppe near Mandalgovi. Its door traditionally faces south, and many families still live in one.", "credit": "Mark Fischer / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Mongolian_Ger.jpg"}, {"id": "t-moscow", "image": "places/t-moscow.jpg", "level": 2, "country": "Russia", "title": "A wooden church in the snow", "alt": "A small dark wooden church with a steep pointed roof among frosty birch trees and snow.", "clue": "Log churches built without nails, birch trees and deep winter snow, in a historic town north-east of a great capital.", "story": "This wooden Church of St Nicholas stands in Suzdal, Russia. It was moved there from a village in 1960 as part of a museum of wooden architecture.", "credit": "Hamerani / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Nikolskaya_wooden_church.jpg"}, {"id": "t-nairobi", "image": "places/t-nairobi.jpg", "level": 2, "country": "Kenya", "title": "A painted minibus", "alt": "A minibus covered in bright graffiti-style art at a busy city junction.", "clue": "Brightly painted shared minibuses, often with music blaring, are how this East African capital gets around.", "story": "Matatus are the shared minibuses of Nairobi in Kenya. Owners compete to have the boldest art, lights and music.", "credit": "Lebu Ayiga / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:KiXX_matatu_at_a_busy_Nairobi_intersection.jpg"}, {"id": "t-nizwa", "image": "places/t-nizwa.jpg", "level": 2, "country": "Oman", "title": "Battlements and a minaret", "alt": "Rounded sandy battlements of a fort in the foreground, with a minaret and a town below and hazy mountains behind.", "clue": "Fort battlements and a mosque minaret in a mountain oasis town known for its dates and silver.", "story": "Nizwa Fort in Oman was built in the 1600s around a huge round tower, with views over the palm groves. The town holds a lively Friday market and is known for its dates.", "credit": "Martin Falbisoner / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Nizwa_Fort_and_Minaret_of_Friday_Mosque.JPG"}, {"id": "t-oaxaca", "image": "places/t-oaxaca.jpg", "level": 2, "country": "Mexico", "title": "A colourful street", "alt": "A street of brightly painted houses leading to a twin-towered stone church.", "clue": "Bright painted houses and a baroque church in a southern city known for chocolate and seven kinds of mole sauce.", "story": "This street is in Oaxaca, Mexico. The city is famous for its mole sauces, its markets and its Day of the Dead celebrations.", "credit": "Hajor / Wikimedia Commons", "licence": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "source": "https://commons.wikimedia.org/wiki/File:Mexico.Oax.Oaxaca.streets.01.jpg"}, {"id": "t-okavango", "image": "places/t-okavango.jpg", "level": 2, "country": "Botswana", "title": "Poling through the delta", "alt": "A person standing in a narrow wooden canoe and pushing it along with a pole across calm blue water and reeds.", "clue": "Poling a dugout canoe through a delta whose river flows into a desert and never reaches the sea.", "story": "The Okavango Delta in Botswana is fed by a river that runs into the Kalahari and spreads out instead of reaching the sea. Guides pole visitors through it in canoes called mokoro.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Traves%C3%ADa_del_delta_del_Okavango_en_makoro,_Botsuana,_2018-07-31,_DD_07.jpg"}, {"id": "t-pakistan", "image": "places/t-pakistan.jpg", "level": 2, "country": "Pakistan", "title": "A painted truck in the mountains", "alt": "A brightly painted and decorated truck on a mountain highway between rocky peaks.", "clue": "Trucks decorated with flowers, mirrors and chains drive a high mountain highway towards China.", "story": "Truck art is a famous folk art in Pakistan. This road, the Karakoram Highway, is one of the highest paved roads in the world.", "credit": "Mehtab Alam / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Truck_Art.jpg"}, {"id": "t-porto", "image": "places/t-porto.jpg", "level": 2, "country": "Portugal", "title": "Houses along the river", "alt": "Colourful houses stacked up a steep riverbank, with boats on a wide river.", "clue": "Colourful houses tumble down to a river that gave its name to a sweet wine.", "story": "The Ribeira quarter of Porto lines the Douro river. Port wine was shipped downriver from the vineyards in flat-bottomed boats called rabelos.", "credit": "Diego Delso|permission= / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Cais_da_Ribeira,_Oporto,_Portugal,_2012-05-09,_DD_14.JPG"}, {"id": "t-quebec", "image": "places/t-quebec.jpg", "level": 2, "country": "Canada", "title": "A castle-like hotel above the old town", "alt": "A green-roofed, castle-like hotel above old stone houses, with snow in a park in front.", "clue": "A walled old town where the street signs are in French, on a cliff above a great river.", "story": "Quebec City is the only walled city north of Mexico in the Americas. The castle-like building is the Château Frontenac hotel, opened in 1893.", "credit": "Wilfredo Rafael Rodriguez Hernandez / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Park_in_Quebec_City_with_a_monument.jpg"}, {"id": "t-rothenburg", "image": "places/t-rothenburg.jpg", "level": 2, "country": "Germany", "title": "A half-timbered corner", "alt": "A cobbled street fork with a half-timbered yellow house, pastel houses and a stone gate tower, with walkers.", "clue": "Half-timbered houses and a gate tower in a walled medieval town on a \"Romantic Road\".", "story": "The Plönlein, \"little square\", is in Rothenburg ob der Tauber, Germany. The town's medieval walls still run all the way round, and you can walk along them.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Pl%C3%B6nlein,_Rothenburg_ob_der_Tauber,_Alemania,_2023-06-17,_DD_36.jpg"}, {"id": "t-seoul", "image": "places/t-seoul.jpg", "level": 2, "country": "South Korea", "title": "A festival for an alphabet", "alt": "Dancers on an outdoor stage beside a large seated bronze statue of a king, with a mountain behind.", "clue": "A seated king who invented an alphabet in 1443, in a capital ringed by mountains.", "story": "This stage was set up beside the statue of King Sejong in Seoul, South Korea, to celebrate Hangul, the alphabet he created. Hangul Day is a national holiday on 9 October.", "credit": "Taehyung Jin / Wikimedia Commons", "licence": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Celebrating_The_Invention_Of_Hangul_1_(125014281).jpeg"}, {"id": "t-sweden", "image": "places/t-sweden.jpg", "level": 2, "country": "Sweden", "title": "Red houses in the frost", "alt": "Red wooden houses with white trim among frosted birch trees in winter.", "clue": "Wooden houses painted a deep red made from copper-mine waste, among birches in a northern kingdom.", "story": "These red houses were built for paper-mill workers at Hallstavik, Sweden, in 1914–15. The paint, Falu red, comes from the copper mine at Falun.", "credit": "ArildV / Wikimedia Commons", "licence": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Hallsta_Paper_Mill_January_2012g.jpg"}, {"id": "t-tallinn", "image": "places/t-tallinn.jpg", "level": 2, "country": "Estonia", "title": "A town hall with a spire", "alt": "A Gothic stone town hall with a slender spire on a cobbled square, with colourful old houses and café umbrellas.", "clue": "A Gothic town hall with a slender spire on a cobbled medieval square near the Baltic Sea.", "story": "Tallinn Town Hall in Estonia is the oldest surviving town hall in Northern Europe. The weathervane on its spire, Old Thomas, is a symbol of the city.", "credit": "Ivar Leidus / Wikimedia Commons", "licence": "CC BY-SA 3.0 EE", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/ee/deed.en", "source": "https://commons.wikimedia.org/wiki/File:Tallinna_Raekoda_11-06-2013.jpg"}, {"id": "t-tbilisi", "image": "places/t-tbilisi.jpg", "level": 2, "country": "Georgia", "title": "Carved wooden balconies", "alt": "An old house with carved wooden balconies among cypress trees and a lamp post.", "clue": "Carved wooden balconies like these hang over the old streets of a capital in the Caucasus.", "story": "Old Tbilisi is famous for its carved wooden balconies. Georgian is written in its own alphabet, used for no other national language.", "credit": "Marcin Konsek / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:2014_Tbilisi,_Domy_na_Starym_Mie%C5%9Bcie_(04).jpg"}, {"id": "t-valparaiso", "image": "places/t-valparaiso.jpg", "level": 2, "country": "Chile", "title": "A house on the hill", "alt": "A pale blue wooden house with a red roof and dormer windows on a hillside street with old lamp posts.", "clue": "Painted wooden houses on steep hills above a Pacific port, linked to the harbour by old funicular lifts.", "story": "This house is on Cerro Alegre in Valparaíso, Chile. Many hillside houses were built by European merchants in the 1800s, and old funiculars still climb the slopes.", "credit": "Carlos Figueroa Rojas / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Casa_en_calle_Miramar,_Cerro_Alegre,_Valpara%C3%ADso_20201102_93.jpg"}, {"id": "t-yerevan", "image": "places/t-yerevan.jpg", "level": 2, "country": "Armenia", "title": "A round theatre", "alt": "A round stone theatre building with arched windows on a wide square under a clear blue sky.", "clue": "A capital built of pink and grey volcanic stone, in sight of a mountain from the story of Noah's ark.", "story": "The Opera Theatre in Yerevan, Armenia, was designed by Alexander Tamanian and opened in 1933.", "credit": "Diego Delso / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:%C3%93pera,_Erev%C3%A1n,_Armenia,_2016-10-03,_DD_13.jpg"}, {"id": "t-zanzibar", "image": "places/t-zanzibar.jpg", "level": 2, "country": "Tanzania", "title": "Verandas by a garden", "alt": "Old white houses with dark red trim and wooden verandas beside a small garden with a flowering bush and big trees.", "clue": "Shady old merchant houses with deep verandas on a spice island in the Indian Ocean.", "story": "This square is in Stone Town, the old heart of Zanzibar City in Tanzania. Zanzibar was famous for its cloves, and Swahili, Arab, Indian and European styles mix in its buildings.", "credit": "Timothy A. Gonsalves (Tagooty) / Wikimedia Commons", "licence": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:North_Kelele_Square_Stone_Town_Oct26_A7CR_14685.jpg"}];
